    /**
     * 跳转到其他的游戏
     */
    static jumpToGame(gameId: number) {
        if (!gameId || gameId == Global.gameId) return;

        let webSrc = WebMsgHandler.webSrc;
        if (WebMsgHandler.webSrc.serverDebug) {
            let web = Global.cdn + "/index.html?";
            let webArgs = encodeURIComponent(`serverDebug=${webSrc.serverDebug}&money=${webSrc.money}&moneyType=${webSrc.moneyType}
                &id=${gameId}&uid=${webSrc.uid}&homeUrl=${webSrc.homeUrl}&lang=${webSrc.lang}`);
            let url = web + webArgs;
            this.c2sStat(StatConst.ITEMS_SKIP_GAME);
            this.setTopHref(url);
        } else {
            let data = {
                token: Global.token,
                gameId: gameId,
                language: Global.language,
                closeBack: Global.closeBack,
                homeUrl: Global.homeUrl,
            }
            let pack: HttpReqPack = HttpReqPack.create(GameHttpData.gameApi + "redirect?", JSON.stringify(data), HttpMethod.POST);
            HttpMgr.Instance().send(pack, null, (param: HttpRespPack) => {
                let data: HttpRespPack = param;

                Log.e("jumpToGame:", data);
                if (data && data.code == 200) {
                    this.c2sStat(StatConst.ITEMS_SKIP_GAME);
                    this.setTopHref(data.data);
                } else {
                    Log.e("跳转地址错误：", data);
                    ComponentMgr.showTips("This game has not been started yet");
                }
            });
        }
    }

