    /**
     * 随机[min,max]中整数，除了excludes列表中整数
     * @param min 
     * @param max 
     * @param excludes 
     * @returns 
     */
    static randomIntEx(min: number, max: number, excludes?: number[]) {
        if (!excludes || excludes.length == 0) return GameUtils.randomInt(min, max + 1);

        let arr: number[] = [];
        for (let i = min; i <= max; ++i) {
            if (excludes.indexOf(i) == -1) {
                arr.push(i);
            }
        }

        return arr[GameUtils.randomInt(0, arr.length)];
    }

