    /**渐隐缓动 */
    static fadeOut(node: Node, cb?: Function, time = 0.5) {
        let op = node.getComponent(UIOpacity);
        if (!op) op = node.addComponent(UIOpacity);

        Tween.stopAllByTarget(op);
        node.active = true;
        op.opacity = 255;
        tween(op)
            .to(time, { opacity: 0 })
            .call(cb || (() => { }))
            .start();
    }

    /**渐显缓动 */
    static fadeIn(node: Node, cb?: Function, time = 0.5, cbDelay = 0) {
        let op = node.getComponent(UIOpacity);
        if (!op) op = node.addComponent(UIOpacity);

        Tween.stopAllByTarget(op);
        node.active = true;
        op.opacity = 0;
        tween(op)
            .to(time, { opacity: 255 })
            .delay(cbDelay)
            .call(cb || (() => { }))
            .start();
    }

    /**
     * 缩放与透明度缓动
     * @param node 
     * @param toScale 
     * @param toOp 
     * @param cb 
     * @param time 
     */
    static scaleFadeTween(node: Node, toScale: number, toOp: number, cb?: Function, time = 1) {
        let op = node.getComponent(UIOpacity);
        if (!op) op = node.addComponent(UIOpacity);
        Tween.stopAllByTarget(op);
        tween(op)
            .to(time, { opacity: toOp })
            .start();

        Tween.stopAllByTarget(node);
        tween(node)
            .to(time, { scale: new Vec3(toScale, toScale) })
            .call(cb || (() => { }))
            .start();
    }

