    //同步两个spine的动画
    static asyncSkeleton(toSke: sp.Skeleton, fromSke: sp.Skeleton) {
        if (!toSke || !fromSke) return
        //皮肤
        let skinName = (fromSke as any).attachUtil?._skeleton?.["skin"]?.name;
        if (!skinName) {
            skinName = fromSke["defaultSkin"]
        }
        if (skinName) {
            toSke.setSkin(skinName)
        }

        //事件
        if (fromSke["_listener"]) {
            toSke.setCompleteListener(fromSke["_listener"]["complete"])
            toSke.setEventListener(fromSke["_listener"]["event"])
        }

        //动画
        toSke.timeScale = fromSke.timeScale
        if (fromSke.getState() && fromSke.getState().tracks) {
            let track = fromSke.getState().tracks[0]
            if (track) {
                toSke.setAnimation(0, fromSke.animation, track.loop)
                toSke.updateAnimation(track.trackTime)
            }
        }
    }
    //同步spine的信息
    static getSkeletonAsyncInfo(fromSke: sp.Skeleton) {
        let info = {}
        if (!fromSke) return info

        //皮肤
        let skinName = (fromSke as any).attachUtil?._skeleton?.["skin"]?.name;
        if (!skinName) {
            skinName = fromSke["defaultSkin"]
        }
        info["skinName"] = skinName
        //事件
        if (fromSke["_listener"]) {
            info["complete_listener"] = fromSke["_listener"]["complete"]
            info["event_listener"] = fromSke["_listener"]["event"]
        }
        info["timeScale"] = fromSke.timeScale
        //动画
        if (fromSke.getState() && fromSke.getState().tracks) {
            let track = fromSke.getState().tracks[0]
            if (track) {
                info["animation"] = fromSke.animation
                info["loop"] = track.loop
                info["trackTime"] = track.trackTime
            }
        }
        //挂点
        info["sockets"] = fromSke.sockets
        return info
    }

    //同步两个spine的动画
    static asyncSkeletonByInfo(toSke: sp.Skeleton, info) {
        if (!toSke || !info) return
        //皮肤
        if (info["skinName"]) {
            toSke.setSkin(info["skinName"])
        }

        //事件
        toSke.setCompleteListener(info["complete_listener"])
        toSke.setEventListener(info["event_listener"])

        //动画
        toSke.timeScale = info["timeScale"]
        if (info["animation"]) {
            toSke.setAnimation(0, info["animation"], info["loop"] ?? false)
            toSke.updateAnimation(info["trackTime"] ?? 0)
        }
        //挂点
        toSke.sockets = info["sockets"] ?? []
    }
    /**
     * 强制结束spine动画 会触发事件监听回调
     * @param ske 
     * @returns 
     */
    static forceEndSkeleton(ske: sp.Skeleton) {
        if (!ske) return
        //暂停 不处理
        if (ske.paused) return
        let state = ske.getState();
        let track = state.tracks[0];
        if (!track)
            return;

        if (track.trackTime >= track.animationEnd) {
            //当前时间大于结束时间 结束了
            //Log.w("当前时间大于结束时间 当结束了")
            return
        }
        ske.updateAnimation(track.animationEnd)
    }

    /**
     * 同步同一个spine特效里两个动作
     * @param ske 
     * @param aniName 
     * @returns 
     */
    static asyncSkeletonTrackTime(ske: sp.Skeleton, aniName: string) {
        let state = ske.getState();
        let track = state.tracks[0];
        if (!track)
            return;
        let loop = track.loop;
        let trackTime = track.trackTime;
        if (trackTime > track.animationEnd)
            trackTime = trackTime % track.animationEnd;
        Log.d('trackTime:', trackTime)
        let aniTrack = ske.setAnimation(0, aniName, loop);
        aniTrack.trackTime = trackTime;
    }

    /**
     * @description: 放大缩小
     * @param {Node} node
     * @param {number} tweenTime 总时间
     * @param {Function} callBack
     * @param {number} times 放大缩小次数
     * @param {number} scaleIn 
     * @param {number} scaleOut
     * @return {*}
     */
    static scaleInOutTween(node: Node, tweenTime: number, callBack?: Function, times?: number, scaleIn?: number, scaleOut?: number) {
        Tween.stopAllByTarget(node);
        times = times ?? 1
        let selfScale = node.scale.x
        scaleIn = scaleIn ?? selfScale * 2
        scaleOut = scaleOut ?? selfScale
        let oneTime = tweenTime / times / 2
        let tweenScale = tween(node).to(oneTime, { scale: new Vec3(scaleIn, scaleIn) }).to(oneTime, { scale: new Vec3(scaleOut, scaleOut) }).union()

        if (times > 1) {
            tweenScale.repeat(times)
        }

        let complete = tween(node).call(() => {
            callBack?.()
        })
        tween(node).sequence(tweenScale, complete).start()
    }

