    //同步同一个Animation两个动作时间
    static asyncAnimationClipTime(ani: Animation, fromClip: string, toClip: string) {
        if (!ani) return
        let fromState = ani.getState(fromClip)
        //Log.d("fromState", fromState)
        if (fromState && (fromState["_isPlaying"])) {
            ani.play(toClip)
            let toState = ani.getState(toClip)
            if (toState) {
                toState.time = fromState.time
            }

        }
    }
