import { _decorator, Component, Prefab, instantiate, EventTouch, NodeEventType, Node, SpriteFrame, Sprite, UITransform, ScrollView, size, Label, warn, Vec3 } from 'cc';
import { UIView } from '../../../../../scripts/framework/ui/UIView';
import { Global } from '../../../../../scripts/main/Global';
import { HttpReqPack } from '../../../../../scripts/common/net/http/HttpReqPack';
import GameHttpData from '../../GameHttpData';
import { HttpMethod } from '../../../../../scripts/common/define/EnumDefine';
import { HttpMgr } from '../../../../../scripts/common/net/http/HttpMgr';
import { HttpRespPack } from '../../../../../scripts/common/net/http/HttpRespPack';
import { GameSelectItem } from './GameSelectItem';
import { ResManager } from '../../../../../scripts/framework/manager/ResManager';
import { BagItem } from '../bag/BagItem';
import { ItemType } from '../bag/BagModel';
import { UIManager } from '../../../../../scripts/framework/ui/UIManager';
import { UIID_GAME } from '../../UIGameDefined';
const { ccclass, property } = _decorator;

@ccclass('GameAwardView')
export class GameAwardView extends UIView {
    private _data:any = null;
    private _uiList:any = {};
    private _itemList:any = [];


    onLoad(): void {
        this.initUI();
        this.bindEvent(); 
    }

    start() {
    }

    protected onDestroy(): void {
        this.unscheduleAllCallbacks();
    }

    public initUI() {
        
    }

    public bindEvent() {
        // this._uiList["btn_close_selectitemPop"].on(NodeEventType.TOUCH_END, ()=>{
        //     this.node.active = false;
        // }, this);
    }

    public onOpen(data:any): void {
        // this._data = data;

        this.SerializableUIControlNode(this.node);

        // let game = this._data?.awardConf?.game;
        // this.undateScroll(game);

        // let tb = [1, 2, 3, 4];
        // this.undateScroll(tb);

        let name = this.getLanguageValue(data.name?.language);
        if (!name || name == "") {
            name = data?.name?.defaultValue;
        }
        this._uiList["Label_name-001"].getComponent(Label).string = name || "";;


        this.unscheduleAllCallbacks()
        this.scheduleOnce(()=>{
            UIManager.getInstance().closeToUI(UIID_GAME.GameAwardView);
        }, 5);
    }

    public getLanguageValue(language:any) {
        if (!language) {
            return "1111111111111";
        }

        for (let vo of language) {
            if (vo.lang == Global.language) {
                return vo.value;
            }
        }
    }

    private SerializableUIControlNode(root:Node) {
        if (!root) {
            return;
        }
        let children = root.children;
        for (let k in children) {
            let child = children[k];
            let name = child.name;
            this._uiList[name] = child;
            if (child.children.length >= 1) {
                this.SerializableUIControlNode(child);
            }
        }
    }

    public undateScroll(data:any) {
        let ScrollView_task:Node = this._uiList["ScrollView_task"];
        let scroll_size = ScrollView_task.getComponent(UITransform).contentSize;
        let conten = ScrollView_task.getComponent(ScrollView).content;
        let conten_size = conten.getComponent(UITransform).contentSize;
        let conten_in_size = size(conten_size.width, conten_size.height);
        let item_temp = conten.getChildByName("item");

        let len = data.length;
        let item_width = 100;
        let item_height = 100;

        let colNum = 1;

        let check_len = Math.ceil(len / colNum);

        if (item_width * check_len > scroll_size.width) {
            conten_in_size.width = item_width * check_len;
        } else {
            conten_in_size.width = scroll_size.width;
        }

        conten.getComponent(UITransform).setContentSize(conten_in_size);

        for (let i = 0; i < len; i++) {
            let vo = data[i];

            let item:Node = this._itemList[i];
            if (!item) {
                item = instantiate(item_temp);
                conten.addChild(item);
                this._itemList[i] = item;
            }

            item.active = true;
            let x = item_width/2 + i*item_width;
            let y = -item_height/2;
            item.setPosition(x, y);

            ResManager.Instance().load("gamesCommon", "resources/prefabs/bag/BagItem", Prefab, null, (_data) => {
                if (_data && _data.data && _data.data instanceof Prefab) {
                    let itemNode = instantiate(_data.data);
                    if(!itemNode) {
                        warn(`instantiate BagItem node failed`);
                        return ;
                    }
    
                    let bagItem = itemNode.getComponent(BagItem);
                    // if (id == null && type == 2) {
                    //     bagItem.setEasyData(id, ItemType.Score, score);
                    // } else {
                    //     bagItem.setEasyData(id, propType, amount);
                    // }
                    // bagItem.setEasyData(null, ItemType.Score, 1);
                    bagItem.node.scale = new Vec3(0.6, 0.6, 0.6);
                    item.addChild(itemNode);
                }
                else {
                    warn(`load prefab : resources/prefabs/bag/BagItem fail`);
                    return;
                }
            });
            
            // let taskItem = item.getComponent(GameSelectItem);
            // taskItem.setData(vo, this._data);
        }
    }
}