/**
 * @description 使用虚宝卡接口，可用虚宝卡的滚轮游戏必须实现，参考3000185主界面
 * @author guohuo
 */
export interface ComUseXBKInt {
    /**
     * 返回当前游戏是否可以使用虚宝卡的状态码
     * @return 0:可以使用 1：不在空闲状态 ...
     */
    getStatusWithUseXBK(): number;

    /**
     * 经过判断条件满足开始使用虚宝卡，启动滚轮
     * 相当于点击滚轮界面‘开始’按钮
     * (该父类调用子类getStatusWithUseXBK判断是否可用，并设置数据)
     * @param bet 下注数目
     * @param times 滚轮次数
     */
    // 记录下注数目及滚轮次数，是否为空可作为是否正在使用虚宝卡的状态
    usingXBKObj: { id: string, bet: number, times: number };
    startUseXBK(id: string, bet: number, times: number): boolean;

    /**
     * 本次虚宝卡使用结束调用
     */
    endUseXBK(): void;

    /**
     * 每使用完一次虚宝卡后调用
     */
    afterUseXBK(): void;

    /**
     * 判断是否正在使用虚宝卡
     */
    isUsingXBK(): boolean;
}