import { _decorator, Component, Label, random, Vec3 } from 'cc';
import { Eventer } from '../../../scripts/framework/Eventer';
import { GameEventType } from './GameEventType';
import { Global } from '../../../scripts/main/Global';
import { ScreenType, UIView } from '../../../scripts/framework/ui/UIView';
import WebMsgHandler from '../../../scripts/common/net/http/WebMsgHandler';
import { GameUtils } from '../../../scripts/common/utils/GameUtil';
const { ccclass, property } = _decorator;

@ccclass('ComView')
export class ComView extends UIView {

    @property(Label)
    lab_time: Label;

    @property({ type: Label, tooltip: '玩家账号id' })
    lab_userId: Label;

    start() {
        this.lab_userId.getComponent(Label).string = Global.account;
    }

    public init(): void {
        this.onScreenSwitch();
        Eventer.getInstance().on(GameEventType.ScreenSwitch, this.onScreenSwitch, this);
        Eventer.getInstance().on(GameEventType.OnLoginSuccess, this.onLoginSuc, this);
    }

    protected onDestroy(): void {
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
        Eventer.getInstance().offName(GameEventType.OnLoginSuccess, this);
    }


    update(deltaTime: number) {

        if (Global.playback) {
            this.lab_time.node.active = false;
        } else {
            let data = new Date();
            let minutes = data.getMinutes();
            let min = minutes < 10 ? "0" + minutes : minutes;
            this.lab_time.string = data.getHours() + ":" + min;
        }
    }

    private onScreenSwitch(): void {
        if (Global.gameScreenType == ScreenType.Landscape) {
            this.node.angle = 0;
            this.lab_time.node.setPosition(new Vec3(-585, 335, 0));
            this.lab_userId.node.setPosition(new Vec3(625, 335, 0));
        } else {
            // this.node.angle = 90;
            this.lab_time.node.setPosition(new Vec3(-310, -610, 0));
            this.lab_userId.node.setPosition(new Vec3(340, -610, 0));
        }
    }

    private generateRandomString(): string {
        const length = GameUtils.randomInt(7, 15); // 生成 7 到 14 之间的随机长度
        const characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'; // 包含字母和数字的字符串
        let result = '';

        for (let i = 0; i < length; i++) {
            const randomIndex = Math.floor(Math.random() * characters.length);
            let chat = characters.charAt(randomIndex);
            if (Math.random() > 0.5) chat = chat.toLocaleLowerCase();
            result += chat;
        }

        return result;
    }

    private onLoginSuc() {
        let userId = Global.account;
        if (WebMsgHandler.webSrc.serverDebug)
            userId = this.generateRandomString();
        this.lab_userId.getComponent(Label).string = userId;
    }
}