import { Component, Label, Node, NodeEventType, Prefab, ProgressBar, Sprite, SpriteFrame, UITransform, Vec3, _decorator, instantiate, warn } from "cc";
import { Global } from "../../../../../scripts/main/Global";
import { ResManager } from "../../../../../scripts/framework/manager/ResManager";
import { BUNDLE_NAME, UIID_GAME } from "../../UIGameDefined";
import { GameTaskEvent, GameTaskModel } from "./GameTaskModel";
import { Eventer } from "../../../../../scripts/framework/Eventer";
import UIUtils from "../../../../../scripts/framework/ui/UIUtils";
import GamesData from "../../GamesData";
import { UIManager } from "../../../../../scripts/framework/ui/UIManager";
import { ItemType, ItemVo } from "../bag/BagModel";
import { GameCommonManager } from "../../GameCommonManager";
import { BagItem } from "../bag/BagItem";
import DateUtil from "../../../../../scripts/framework/utils/DateUtil";
import { GameCommonModel } from "../../GameCommonModel";
import { GameComUtils } from "../../utils/GameComUtils";
import { StatConst } from "../../stat/StatConst";
import { GameSelectItem } from "./GameSelectItem";
import { HttpReqPack } from "../../../../../scripts/common/net/http/HttpReqPack";
import GameHttpData from "../../GameHttpData";
import { HttpMethod } from "../../../../../scripts/common/define/EnumDefine";
import { HttpMgr } from "../../../../../scripts/common/net/http/HttpMgr";
import { HttpRespPack } from "../../../../../scripts/common/net/http/HttpRespPack";
import i18n from "../../../../../scripts/framework/language/i18n";
import ComponentMgr from "../../../../../scripts/mgr/ComponentMgr";

const { ccclass, property } = _decorator;

@ccclass('GameTaskItems')
export class GameTaskItems extends Component {
    private _data: any = null;
    private _uiList: any = {};
    private _chect_data: any = null;

    onLoad(): void {

        this.initUI();
        this.bindEvent();
    }

    start() {

    }

    private SerializableUIControlNode(root: Node) {
        if (!root) {
            return;
        }
        let children = root.children;
        for (let k in children) {
            let child = children[k];
            let name = child.name;
            this._uiList[name] = child;
            if (child.children.length >= 1) {
                this.SerializableUIControlNode(child);
            }
        }
    }

    public initUI() {
        this.SerializableUIControlNode(this.node);
    }

    public bindEvent() {
        this._uiList["button_get"]?.on(NodeEventType.TOUCH_END, () => {
            // if (this._chect_data?.rewardList[0]?.status != 1) {
            if (this._chect_data?.status != 1) {
                // let data:any = {};
                // data.awardType = this._data?.vip.phaseList[0]?.rewardList[0]?.type;
                // data.phase = this._data?.vip.phaseList[0]?.phase;
                // data.taskId = this._data?.awardConf?.taskId;
                // data.gameId = Global.gameId;
                // data.playerId = null;
                // GameTaskModel.getInstance().c2sSlotTaskawards(data);
                // } else if (this._data?.vip.phaseList[0]?.rewardList[0]?.status == 2) {

                // Log.d("this._data?.awardConf?.game?.length ===", this._data?.awardConf?.game?.length);
                if (this._data?.awardConf?.game?.length > 1) {
                    Eventer.getInstance().emit(GameTaskEvent.open_task_select_pop_view, this._data);
                } else {
                    let gameId = this._data?.awardConf?.game[0]?.gameId;
                    GameComUtils.c2sStat(StatConst.CLICK_TASK_GO);
                    Eventer.getInstance().emit(GameTaskEvent.open_task_pop_view, gameId);
                }
            }

        }, this);

        // this._uiList["img_lock"].on(NodeEventType.TOUCH_END, ()=>{
        this._uiList["list_bg"]?.on(NodeEventType.TOUCH_END, () => {
            if (this._chect_data?.isLock) {
                ComponentMgr.showTipsById(2001018);
            }
        }, this);

        this._uiList["img_complete"]?.on(NodeEventType.TOUCH_END, () => {
            ComponentMgr.showTipsById(2001019);
        }, this);
    }

    public setData(data: any) {
        this._data = data;

        if (!data || !data.vip || !data.vip.phaseList) {
            // Log.d("data.awardConf?.name?.defaultValue; ==", data)
            return;
        }

        let TASK_GAME_TYPE = {
            [2]: "fishing",
            [3]: "slots"
        }
        // Log.d("setData === data.gameId, data.gameType", data?.awardConf?.game[0]?.gameId, data?.awardConf?.game[0]?.gameType, Global.gameId, TASK_GAME_TYPE[Global.gameType]);

        let chect_data = data.vip?.phaseList[data.vip?.phaseList.length - 1];
        // for (let vo of data.vip?.phaseList) {
        //     if (vo?.rewardList[0]?.status != 1) {
        //         chect_data = vo;
        //         break;
        //     }
        // }

        this._chect_data = chect_data;
        this._chect_data.isReward = true
        let Label_name: Node = this._uiList["Label_name"];
        let Label_tips: Node = Label_name.parent.getChildByName("Label_tips")
        let Progress_bar: Node = this._uiList["Progress_bar"];
        let Label_progress: Node = this._uiList["Label_progress"];
        let Label_get: Node = this._uiList["Label_get"];

        let name = this.getLanguageValue(data.awardConf?.name?.language);
        if (!name || name == "") {
            name = data.awardConf?.name?.defaultValue;
        }
        Label_name.getComponent(Label).string = name || "";


        let tips = this.getLanguageValue(data.awardConf?.desc?.language);
        if (!tips || tips == "") {
            tips = data.awardConf?.desc?.defaultValue;
        }

        let curVip = data?.curVipLv || 0;
        // Log.d("curVip ===", data?.curVipLv, curVip, chect_data?.vip, name)

        if (chect_data?.vip != undefined && chect_data?.vip != null && chect_data?.vip >= 0) {
            if (curVip < chect_data?.vip) {
                tips = tips + "     " + "(VIP" + chect_data?.vip + " can get awards)"
            }
        }

        Label_tips.getComponent(Label).string = tips;

        Progress_bar.getComponent(ProgressBar).progress = chect_data?.progress / chect_data?.betNum;

        // Log.d("chect_data?.progress ====", String(chect_data?.progress), chect_data?.progress, GameCommonModel.getInstance().coinRate, chect_data?.progress * GameCommonModel.getInstance().coinRate)

        Label_progress.getComponent(Label).string = GamesData.exact(chect_data?.progress * GameCommonModel.getInstance().coinRate) + "/" + GamesData.exact(chect_data?.betNum * GameCommonModel.getInstance().coinRate);

        Label_get.getComponent(Label).string = "RECEIVE";

        for (let i = 1; i <= 7; i++) {
            this._uiList["Sprite-00" + i].active = false;
        }

        //奖励ICON
        if (chect_data?.rewardList) {
            let isHavePopup2 = chect_data?.rewardList.length > 1 ? true : false // 是否显示2级弹窗，图标多于1个显示
            for (let i = 1; i <= chect_data?.rewardList.length; i++) {
                let vo = chect_data?.rewardList[i - 1];

                let Sprite_icon: Node = this._uiList["Sprite-00" + i];
                Sprite_icon.active = true;
                Sprite_icon.getComponent(Sprite).spriteFrame = null;


                let id = vo?.id;
                let amount = vo?.amount ? vo?.amount : 1;
                let propType = vo?.propType;
                let type = vo?.type;
                let score = vo?.score;

                // Log.d("id, type, amount==1==", id, type, amount, name);

                ResManager.Instance().load("gamesCommon", "resources/prefabs/bag/BagItem", Prefab, null, (_data) => {
                    if (_data && _data.data && _data.data instanceof Prefab) {
                        let itemNode = instantiate(_data.data);
                        if (!itemNode) {
                            warn(`instantiate BagItem node failed`);
                            return;
                        }

                        let bagItem = itemNode.getComponent(BagItem);
                        if (id == null && type == 2) {
                            bagItem.setEasyData(id, ItemType.Score, score, false, isHavePopup2, this._chect_data);
                        } else {
                            bagItem.setEasyData(id, propType, amount, false, isHavePopup2, this._chect_data);
                        }

                        bagItem.node.scale = new Vec3(0.45, 0.45, 0.45);
                        Sprite_icon.addChild(itemNode);
                    }
                    else {
                        warn(`load prefab : resources/prefabs/bag/BagItem fail`);
                        return;
                    }
                });
            }
        }


        // this._uiList["SpriteSplash_mask"].active = false;
        if (chect_data?.isLock) {
            this._uiList["img_lock"].active = true;
            this._uiList["img_complete"].active = false;
            this._uiList["button_get"].active = false;

            // this._uiList["SpriteSplash_mask"].active = true;
            // } else if (chect_data?.rewardList[0]?.status == 1) {//领取状态；0-未领取，1已领取, 2-未获得
        } else if (chect_data?.status == 1) {
            this._uiList["img_lock"].active = false;
            this._uiList["img_complete"].active = true;
            this._uiList["button_get"].active = false;
        } else {
            this._uiList["img_lock"].active = false;
            this._uiList["img_complete"].active = false;
            this._uiList["button_get"].active = true;

            // 当前游戏再跳转列表则按钮不显示
            let datas: any[] = this._data?.awardConf?.game;
            this._uiList["Label_get"].getComponent(Label).string = i18n.tr(2001006);
            this._uiList["Label_get"].active = false
            // 按钮处理 0 包含当前 1 只有一个且不包含当前 2 多个且不包含当前
            switch (this.judgeGameList(datas)) {
                case 0:
                    this._uiList["button_get"].active = false
                    break;
                case 1:
                    this._uiList["button_get"].getComponent(Sprite).spriteFrame = null
                    if (datas.length > 0) {
                        this._uiList["button_get"].addComponent(GameSelectItem).setData(datas[0])
                        this._uiList["Label_tips"].getComponent(Label).string = i18n.tr(2001016)
                    }
                    break;
                case 2:
                    // 按钮处理
                    this._uiList["button_get"].getComponent(Sprite).spriteFrame = null
                    this.getIcon(this._uiList["button_get"].getChildByName("Sprite_icon"), datas[0])
                    this._uiList["Label_tips"].getComponent(Label).string = i18n.tr(2001016)
                    break;
                default:
                    // 按钮处理
                    // ResManager.Instance().load(BUNDLE_NAME.gamesCommon, "resources/texture/gameTask/newtask/heng/button_blue/spriteFrame", SpriteFrame, () => { }, (evt: any) => {
                    //     if (evt.data) {
                    //         this._uiList["button_get"].getComponent(Sprite).spriteFrame = evt.data;
                    //     }
                    // });
                    // this._uiList["Label_get"].active = true
                    // this._uiList["Sprite_icon"].active = false
                    // this._uiList["Label_tips"].active = false
                    this._uiList["button_get"].active = false
                    break;

            }
        }
    }
    /*判断游戏绑定列表*/
    private judgeGameList(datas) {
        let curGameId = Global.gameId;
        if (datas) {
            for (let data of datas) {
                if (data.gameId == curGameId) {
                    return 0
                }
            }
            if (datas.length <= 1) {
                return datas.length
            } else {
                return 2
            }
        }
    }
    /*多个游戏显示这个icon*/
    public getIcon(node, data) {
        let str: string = JSON.stringify({ gameId: data.gameId });
        // let str: string = JSON.stringify({ gameId: 3000185 });
        let pack: HttpReqPack = HttpReqPack.create(GameHttpData.gameIconPath, str, HttpMethod.POST);
        HttpMgr.Instance().send(pack, null, (param: HttpRespPack) => {
            let hdata: HttpRespPack = param;

            // GameToolsFunc.dump(hdata);
            if (hdata && hdata.code == 200) {
                ResManager.Instance().loadRemoteImg(hdata.data.squareIcon, false, (spriteFrame: SpriteFrame) => {
                    if (spriteFrame) {
                        node.getComponent(Sprite).spriteFrame = spriteFrame;
                        // this._uiList["Sprite_icon"].getComponent(UITransform).setContentSize(180, 180);
                        // this._uiList["Sprite_icon"].scale = new Vec3(0.2, 0.2, 0.2);
                    }
                });
            }
        });
    }

    public setDataTab3(data: any) {
        this._data = data;

        if (!data || !data.vip || !data.vip.phaseList) {
            return;
        }


        let Label_name: Node = this._uiList["Label_name"];
        let Label_tips: Node = this._uiList["Label_tips"];
        let Label_time: Node = this._uiList["Label_time"];

        let name = this.getLanguageValue(data.awardConf?.name?.language);
        if (!name || name == "") {
            name = data.awardConf?.name?.defaultValue;
        }
        Label_name.getComponent(Label).string = name;

        let chect_data = data.vip?.phaseList[data.vip?.phaseList.length - 1];
        this._chect_data = chect_data;
        this._chect_data.isReward = true
        let tips = this.getLanguageValue(data.awardConf?.desc?.language);
        if (!tips || tips == "") {
            tips = data.awardConf?.desc?.defaultValue;
        }
        Label_tips.getComponent(Label).string = tips;

        let startTime = data.awardConf?.startTime;
        if (startTime) {
            Label_time.getComponent(Label).string = i18n.tr(2001007) + " : " + DateUtil.formatDate("yyyy.MM.dd hh:mm", startTime);
        }

        for (let i = 1; i <= 7; i++) {
            this._uiList["Sprite-00" + i].active = false;
        }
        //奖励ICON
        if (data.vip?.phaseList[0]?.rewardList) {
            let isHavePopup2 = data.vip?.phaseList[0]?.rewardList.length > 1 ? true : false
            for (let i = 1; i <= data.vip?.phaseList[0]?.rewardList.length; i++) {
                // let vo = data.vip?.phaseList[0]?.rewardList[0];
                let vo = data.vip?.phaseList[0]?.rewardList[i - 1];
                let Sprite_icon: Node = this._uiList["Sprite-00" + i];
                Sprite_icon.active = true;
                Sprite_icon.getComponent(Sprite).spriteFrame = null;

                let id = vo?.id;
                let amount = vo?.amount || 1;
                let propType = vo?.propType;
                let type = vo?.type;
                let score = vo?.score;

                // Log.d("id, type, amount===111=", id, type, amount, data.vip?.phaseList[0]?.rewardList.length);

                ResManager.Instance().load("gamesCommon", "resources/prefabs/bag/BagItem", Prefab, null, (_data) => {
                    if (_data && _data.data && _data.data instanceof Prefab) {
                        let itemNode = instantiate(_data.data);
                        if (!itemNode) {
                            warn(`instantiate BagItem node failed`);
                            return;
                        }

                        let bagItem = itemNode.getComponent(BagItem);
                        if (id == null && type == 2) {
                            bagItem.setEasyData(id, ItemType.Score, score, false, isHavePopup2, this._chect_data);
                        } else {
                            bagItem.setEasyData(id, propType, amount, false, isHavePopup2, this._chect_data);
                        }

                        bagItem.node.scale = new Vec3(0.45, 0.45, 0.45);
                        Sprite_icon.addChild(itemNode);
                    }
                    else {
                        warn(`load prefab : resources/prefabs/bag/BagItem fail`);
                        return;
                    }
                });
            }
        }
    }

    public getLanguageValue(language: any) {
        if (!language) {
            return "1111111111111";
        }

        for (let vo of language) {
            if (vo.lang == Global.language) {
                return vo.value;
            }
        }
    }
}