import { Node, _decorator, NodeEventType, Prefab, instantiate } from "cc";
import { UIView } from "../../../../scripts/framework/ui/UIView";
import { GAME_PREF_PATH, UIID_GAME } from "../UIGameDefined";
import { ResManager } from "../../../../scripts/framework/manager/ResManager";
import { Global } from "../../../../scripts/main/Global";
import { Resource } from "../../../../scripts/framework/hall/Resource";
import { Eventer } from "../../../../scripts/framework/Eventer";
import { GameEventType } from "../GameEventType";
import { UIManager } from "../../../../scripts/framework/ui/UIManager";
import { GameCommonManager } from "../GameCommonManager";
import AudioManager from "../../../../scripts/framework/manager/AudioManager";

const { ccclass, property } = _decorator;

@ccclass('GameIntroView')
export class GameIntroView extends UIView {

    @property({ displayName: '游戏介绍内容节点', type: Node })
    private introNode: Node;
    @property({ displayName: '点击节点', type: Node })
    private clickNode: Node;

    private _timer: number = 0;

    start() {
        this.clickNode.on(NodeEventType.TOUCH_END, this.onTouch, this);
    }

    onOpen(...arg) {
        if (Global.skipIntro) {
            this.closeIntro(0);
            return;
        }
        ResManager.Instance().load(Global.gameId.toString(), GAME_PREF_PATH.GAME_INTRO_PREF, Prefab, () => { }, (cache: Resource.CacheData) => {
            let pref: Prefab = <Prefab>cache.data;
            if (!pref) {
                Log.d('This game dose not have GameIntroPref!')
                this.closeIntro(0);
                return;
            }
            this.timedShutdown();
            let node: Node = instantiate(pref);
            this.introNode.addChild(node);
        })
    }

    onClose() {
        this.clickNode.off(NodeEventType.TOUCH_END, this.onTouch, this);
    }

    /**
     * x时间后自动关闭介绍页
     */
    private timedShutdown() {
        this.clearTimedShutdown();
        this._timer = setTimeout(() => {
            this.closeIntro(0);
        }, 5000)
    }

    /**
     * 清除自动关闭介绍页计时器
     * @returns 
     */
    private clearTimedShutdown() {
        if (!this._timer)
            return;
        clearTimeout(this._timer);
    }

    protected onDestroy(): void {
        Eventer.getInstance().emit(GameEventType.GAME_INTRO_VIEW_CLOSE);
        this.clearTimedShutdown();
    }

    /**
     * 关闭
     * @param play 是否有播放游戏介绍页，有介绍页才能skip
     */
    private closeIntro(play: number) {
        let obj = {
            gameid: Global.gameId,
            skip: play //是否已跳过
        }
        GameCommonManager.getInstance().c2javaMarkByShort('skip_intro', obj);

        this.close();
    }

    private onTouch() {
        //第一次交互播放背景音乐 
        AudioManager.Instance().replayMusic();
        this.closeIntro(1);
    }
}