import { Singleton } from "../../../../../scripts/framework/Singleton";
import { GameProtocolId } from "../../gameSocket/GameProtocolId";
import GameSocketManager, { C2S_ProtocolParams, S2C_ProtocolParams } from "../../gameSocket/GameSocketManager";
import { Eventer } from "../../../../../scripts/framework/Eventer";
import { GameEventType } from "../../GameEventType";
import { HttpMethod } from "../../../../../scripts/common/define/EnumDefine";
import { HttpMgr } from "../../../../../scripts/common/net/http/HttpMgr";
import { HttpReqPack } from "../../../../../scripts/common/net/http/HttpReqPack";
import { HttpRespPack } from "../../../../../scripts/common/net/http/HttpRespPack";
import WebMsgHandler from "../../../../../scripts/common/net/http/WebMsgHandler";
import { WinningsBtn } from "./WinningsBtn";
import TimeUtil from "../../../../../scripts/common/utils/TimeUtil";
import GameHttpData from "../../GameHttpData";
import { GameComUtils } from "../../utils/GameComUtils";

export class WinningsMgr extends Singleton<WinningsMgr>() {
    private gameSocketMgr: GameSocketManager;

    public curDatas: WinningVo[]; // 当前的彩金数据
    public newDatas: WinningVo[]; // 最新的彩金数据
    private addDatas: number[] = [0, 0, 0, 0]; // 每ms的增量数据
    private startTime: number = 0;
    private timer: number = 0;
    private timer2: number = 0;

    public curRecords: WinningRecordVo[]; // 当前的中奖记录 
    public newRecords: WinningRecordVo[]; // 最新的中奖记录 

    public otherDatas: any[]; // 其他游戏的彩金数据 gameItem[]

    private winningList: any[] = []; // 中奖记录 rewardItem[]

    public descs: any;

    constructor() {
        super();
        this.gameSocketMgr = GameSocketManager.getInstance();
        this.registerMsgListener();
    }

    public registerMsgListener() {

        this.gameSocketMgr.registerMsgListener<S2C_ProtocolParams>(GameProtocolId.winnings_notice, this.s2cWinningsNotice, this);

        // // test
        // setInterval(() => {
        //     let num = GameComUtils.randomIntEx(1, 10);
        //     this.winningList.push({
        //         name: "diaomao" + num,
        //         level: num,
        //         amout: num * 100,
        //         gameId: 3000185,
        //     });
        //     Eventer.getInstance().emit(GameEventType.winnings_notice);
        // }, 10 * 1000);
        this.c2sWinningsDescs();
    }

    shiftOneWinning() {
        return this.winningList.shift();
    }
    public s2cWinningsNotice(msg: S2C_ProtocolParams<any>) {
        Log.d("s2cBonusReward:", msg);
        if (!msg.succ) return;

        this.winningList.push(msg.message);

        this.c2sWinningsJackpots();
        this.c2sWinningsRecords();

        Eventer.getInstance().emit(GameEventType.winnings_notice);
    }

    public c2sWinningsDescs(data?: any) {
        Log.d("c2sWinningsDescs");
        let src = WebMsgHandler.webSrc;
        let pack: HttpReqPack = HttpReqPack.create(`${GameHttpData.gameAct}prize/getPrizeSetting`, `?gameId=${src.id}&uid=${src.uid}&lan=${src.lang}`, HttpMethod.GET);
        HttpMgr.Instance().send(pack, data, this.s2cWinningsDescs.bind(this));
    }
    private s2cWinningsDescs(msg: HttpRespPack, data: any) {
        Log.d("s2cWinningsDescs:", msg);
        if (msg && msg.code == 200) {
            this.descs = msg.data;
            Eventer.getInstance().emit(GameEventType.winnings_descs);
            if (data && typeof data == 'function') data(msg.data);
        }
    }

    public c2sWinningsJackpots(data?: any) {
        Log.d("c2sWinningsJackpots");
        let src = WebMsgHandler.webSrc;
        let pack: HttpReqPack = HttpReqPack.create(`${GameHttpData.gameAct}prize/getPrizeInfo`, `?gameId=${src.id}&uid=${src.uid}&lan=${src.lang}`, HttpMethod.GET);
        HttpMgr.Instance().send(pack, data, this.s2cWinningsJackpots.bind(this));
    }
    private s2cWinningsJackpots(msg: HttpRespPack, data: any) {
        Log.d("s2cWinningsJackpots:", msg);
        if (msg && msg.code == 200) {
            let newDatas = msg.data?.prizeDetailDataList || [];
            if (newDatas.length) newDatas.sort((a, b) => a.level - b.level);
            if (!this.curDatas || this.curDatas.length == 0) {
                this.startTime = 0;
                this.curDatas = newDatas;
                this.newDatas = newDatas;
                clearInterval(this.timer);
                if (this.curDatas.length) this.timer = setInterval(this.updateJackpotVal.bind(this), 10);
            } else {
                if (newDatas.length == 0) {
                    this.curDatas = this.newDatas = [];
                    this.startTime = 0;
                } else {
                    for (let i = 0; i < this.curDatas.length; ++i) {
                        let curData = this.curDatas[i];
                        let newData = newDatas[i];
                        this.addDatas[i] = 0;
                        if (!newData) continue;
                        curData.maxPrize = newData.maxPrize;
                        let add = newData.poolAmount - curData.poolAmount; // 中奖过后 或者 正在中奖
                        if (add <= 0 || (newData.maxPrize == newData.poolAmount)) {
                            curData.poolAmount = newData.poolAmount;
                        } else {
                            this.addDatas[i] = add / (WinningsBtn.ReqInterval * 1000);
                        }
                    }
                    this.startTime = TimeUtil.getCurMilliTime();
                    this.newDatas = newDatas;
                }
            }

            Eventer.getInstance().emit(GameEventType.winnings_jackpots);
            if (data && typeof data == 'function') data(this.curDatas);

            clearTimeout(this.timer2);
            this.timer2 = setTimeout(this.c2sWinningsJackpots.bind(this), WinningsBtn.ReqInterval * 1000);
            this.c2sWinningsRecords();
        }
    }

    private updateJackpotVal() {
        if (!this.startTime) return;

        let curTime = TimeUtil.getCurMilliTime();
        let passTime = curTime - this.startTime;
        if (passTime < 0) return;
        this.startTime = curTime;

        let datas = this.curDatas;
        for (let i = 0; i < datas.length; ++i) {
            if (this.addDatas[i] == 0) continue;
            let data = datas[i];
            let finalVal = this.newDatas[i].poolAmount;
            let addVal = this.addDatas[i] * passTime;
            let val = data.poolAmount + addVal;
            if (val > finalVal) {
                data.poolAmount = finalVal;
                this.addDatas[i] = 0;
            } else {
                data.poolAmount = val;
            }
            // log("JackPot" + data.level, "jackpotVal: " + data.poolAmount, "addVal: " + addVal, "passTime: " + passTime);
        }

        let allIs0 = true;
        for (let val of this.addDatas) {
            if (val) {
                allIs0 = false;
                break;
            }
        }
        if (allIs0) this.startTime = 0;
    }

    public c2sWinningsRecords(data?: any) {
        Log.d("c2sWinningsRecords");
        let src = WebMsgHandler.webSrc;
        let pack: HttpReqPack = HttpReqPack.create(`${GameHttpData.gameAct}prize/getWinPrizeInfos`, `?gameId=${src.id}&uid=${src.uid}&lan=${src.lang}`, HttpMethod.GET);
        HttpMgr.Instance().send(pack, data, this.s2cWinningsRecords.bind(this));
    }
    private s2cWinningsRecords(msg: HttpRespPack, data: any) {
        Log.d("s2cWinningsRecords:", msg);
        if (msg && msg.code == 200) {
            msg.data.sort((a: WinningRecordVo, b: WinningRecordVo) => {
                return b.date - a.date;
            });
            if (msg.data.length > 50) msg.data.length = 50;
            this.checkNewRobotRecord(msg.data);
            this.curRecords = msg.data;
            Eventer.getInstance().emit(GameEventType.winnings_records);
            if (data && typeof data == 'function') data(this.curRecords);
        }
    }

    _isNewRobotRecord(record: WinningRecordVo) {
        if (!record.sys) return false;

        for (let i = 0; i < this.curRecords.length; ++i) {
            let curRecord = this.curRecords[i];
            if (curRecord.sys == record.sys
                && curRecord.name == record.name
                && curRecord.date == record.date
                && curRecord.level == record.level
                && curRecord.amout == record.amout)
                return false;
        }

        return true;
    }

    checkNewRobotRecord(newRecords: WinningRecordVo[]) {
        if (!this.curRecords) return;

        for (let i = 0; i < newRecords.length; ++i) {
            let newRecord = newRecords[i];
            if (this._isNewRobotRecord(newRecord)) {
                let datas = this.curDatas || [];
                let nxtDatas = this.newDatas || [];
                for (let j = 0; j < datas.length; ++j) {
                    let data = datas[j];
                    let nxtData = nxtDatas[j];
                    if (!nxtData) continue;

                    if (data.level == newRecord.level) {
                        data.poolAmount = nxtData.base;
                        let add = nxtData.poolAmount - data.poolAmount;
                        if (add > 0) {
                            this.addDatas[j] = add / (WinningsBtn.ReqInterval * 900);
                            this.startTime = TimeUtil.getCurMilliTime();
                        }
                        break;
                    }
                }
            }
        }
    }

    public c2sWinningsOtherGames(data?: any) {
        Log.d("c2sWinningsOtherGames");
        let src = WebMsgHandler.webSrc;
        let pack: HttpReqPack = HttpReqPack.create(`${GameHttpData.gameAct}prize/getAllPrizeGameInfo`, `?gameId=${src.id}&uid=${src.uid}&lan=${src.lang}`, HttpMethod.GET);
        HttpMgr.Instance().send(pack, data, this.s2cWinningsOtherGames.bind(this));
    }
    private s2cWinningsOtherGames(msg: HttpRespPack, data: any) {
        Log.d("s2cWinningsOtherGames:", msg);
        if (msg && msg.code == 200) {
            Eventer.getInstance().emit(GameEventType.winnings_other_games, msg.data);
            if (data && typeof data == 'function') data(msg.data);
        }
    }
}

/** 彩金数据 */
export interface WinningVo {
    level,
    maxPrize,
    optId,
    poolAmount,
    base,
}

/** 彩金中奖数据 */
export interface WinningRecordVo {
    name, amout, date, level, sys
}