import { _decorator, find, Node, Sprite, SpriteFrame, PageView, Component, ToggleContainer, instantiate, Toggle, Prefab, warn, Label, math, UITransform, ScrollView } from 'cc';
import { BagInfoItem } from './BagInfoItem';
import { Eventer } from '../../../../../scripts/framework/Eventer';
import { ResManager } from '../../../../../scripts/framework/manager/ResManager';
import { Global } from '../../../../../scripts/main/Global';
import { GameCommonManager } from '../../GameCommonManager';
import { GameEventType } from '../../GameEventType';
import { BagItem } from './BagItem';
import { ActBagInfo_s2c, BagModel } from './BagModel';
import { BagLangConfig } from './BagLangConfig';
import { ScreenType, UIView, UIZIndex } from '../../../../../scripts/framework/ui/UIView';
import { ComAcitivityTab } from '../common/ComActivityTab';
import { GameComUtils } from '../../utils/GameComUtils';
import { StatConst } from '../../stat/StatConst';
const { ccclass, property } = _decorator;

@ccclass('BagView')
export class BagView extends UIView {

    @property({ type: ComAcitivityTab, visible: true })
    private actTab: ComAcitivityTab;
    @property({ type: Node, visible: true })
    private scroll: Node;
    @property({ type: Node, visible: true })
    private scroll2: Node;
    @property({ type: Node, visible: true })
    private content: Node;
    @property({ type: Node, visible: true })
    private content2: Node;
    @property({ type: Node, visible: true })
    private landscape: Node;
    @property({ type: Node, visible: true })
    private portrait: Node;
    private noGoodsNode: Node;

    private scrollPosTimer: number = 0;
    private selIndex: number = -1;
    private bagInfo: ActBagInfo_s2c;
    readonly InfoMaxNum: number = 99;

    init(...args): void {
        this.node.zIndex = UIZIndex.actUI;
    }

    public onOpen() {
        this.addEvents();
        this.initMyUI();
        this.actTab.initData(BagLangConfig.get("tabNames"), "BACKPACK", (i) => this.onTabClicked(i));
        this.actTab.selectTab(1);

        // 获取背包列表数据
        GameCommonManager.getInstance().c2sActBagPage1ToN();
    }

    public onDestroy() {
        Eventer.getInstance().offName(GameEventType.act_bag, this);
        Eventer.getInstance().offName(GameEventType.act_item_use, this);
        Eventer.getInstance().offName(GameEventType.act_bag_info, this);
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
        this.bagInfo = null;
        this.selIndex = -1;
        if (this.timer) clearTimeout(this.timer);
    }

    private onScreenSwitch(): void {
        this.initMyUI();
        let curIndex = this.selIndex + 1;
        this.selIndex = -1;
        this.actTab.screenSwitch();
        this.actTab.selectTab(curIndex);
    }

    private addEvents() {
        Eventer.getInstance().on(GameEventType.act_bag, this.onUpdateBagList, this);
        Eventer.getInstance().on(GameEventType.act_item_use, this.onUpdateBagListAfterItemUse, this);
        Eventer.getInstance().on(GameEventType.act_bag_info, this.onUpdateBagInfo, this);
        Eventer.getInstance().on(GameEventType.ScreenSwitch, this.onScreenSwitch, this);
    }

    onUpdateBagListAfterItemUse() {
        this.onUpdateBagList();
    }

    onUpdateBagList() {
        if (!(this.selIndex == 0 || this.selIndex == 1)) return;

        this.updateItems(this.selIndex);
    }

    timer: number;
    onUpdateBagInfo(msg: ActBagInfo_s2c) {
        if (this.selIndex != 2) return;

        if (!this.bagInfo) this.bagInfo = msg;
        else {
            let curInfo = this.bagInfo;
            if (msg.current != curInfo.current + 1) {
                Log.e("onUpdateBagInfo page error, preInfo = ", curInfo);
                return;
            }

            for (let i = 0; i < msg.records.length; ++i) {
                let record = msg.records[i];
                curInfo.records.push(record);
                if (curInfo.records.length == this.InfoMaxNum) break;
            }
            curInfo.current = msg.current;
            curInfo.pages = msg.pages;
            curInfo.size = msg.size;
            curInfo.total = msg.total;
        }

        if (this.bagInfo.records.length < this.InfoMaxNum && this.bagInfo.current < this.bagInfo.pages) {
            this.timer = setTimeout(() => {
                GameCommonManager.getInstance().c2sActBagInfo(this.bagInfo.current + 1);
            }, 2000);
        }

        this.updateMyInfo();
    }

    private initMyUI() {
        let screenType = Global.gameScreenType;

        this.scroll = find("UILayer/BagView/" + screenType + "/scroll");
        this.scroll2 = find("UILayer/BagView/" + screenType + "/scroll2");
        this.content = find("UILayer/BagView/" + screenType + "/scroll/view/content");
        this.content2 = find("UILayer/BagView/" + screenType + "/scroll2/view/content2");
        this.noGoodsNode = find("UILayer/BagView/" + screenType + "/noGoodsNode");
        this.noGoodsNode.active = false;

        this.content.removeAllChildren();
        this.content2.removeAllChildren();
        this.content2.getComponent(UITransform).height = 0;

        let isLandscape = screenType == ScreenType.Landscape;
        this.landscape.active = isLandscape;
        this.portrait.active = !isLandscape;
    }

    // index: 0-items, 1-info
    private updateItems(index: number) {
        this.scroll.active = true;
        this.scroll2.active = false;

        let preChilds = this.content.children;
        this.content.removeAllChildren();
        if (this.selIndex != index) {
            // this.content.removeAllChildren();
            let scrollView = this.scroll.getComponent(ScrollView);
            scrollView.stopAutoScroll();
            scrollView.scrollToTop();
            this.selIndex = index;
        }

        function findNode(key: string) {
            for (let node of preChilds) {
                if (node.name == key) return node;
            }
            return null;
        }

        let itemVos = BagModel.getInstance().getItemVosByIndex(this.selIndex);
        let self = this;
        for (let i = 0; i < itemVos.length; ++i) {
            let itemVo = itemVos[i];
            // let itemNode = this.content.getChildByName(itemVo.id.toString());
            let itemNode = findNode(itemVo.id.toString());
            if (itemNode) {
                let bagItem = itemNode.getComponent(BagItem);
                bagItem.setData(itemVo);
                continue;
            }
            ResManager.Instance().load("gamesCommon", "resources/prefabs/bag/BagItem", Prefab, null, (data) => {
                if (data && data.data && data.data instanceof Prefab) {
                    let itemNode = instantiate(data.data);
                    if (!itemNode) {
                        warn(`instantiate BagItem node failed`);
                        return;
                    }
                    itemNode.name = itemVo.id.toString();
                    let bagItem = itemNode.getComponent(BagItem);
                    bagItem.setData(itemVo);
                    self.content.addChild(itemNode);
                }
                else {
                    warn(`load prefab : resources/prefabs/bag/BagItem fail`);
                    return;
                }
            });

        }

        this.noGoodsNode.getComponent(Label).string = "No Slotmania Card.";
        this.noGoodsNode.active = itemVos.length == 0;
    }

    private updateMyInfo() {
        this.scroll2.active = true;
        this.scroll.active = false;

        this.selIndex = 2;

        if (!this.bagInfo) {
            GameCommonManager.getInstance().c2sActBagInfo(1);
            this.content2.removeAllChildren();
            this.noGoodsNode.active = true;
            this.noGoodsNode.getComponent(Label).string = "Loading...";
            return;
        }

        if (this.bagInfo.records.length == 0) {
            this.content2.removeAllChildren();
            this.bagInfo = null;
            this.noGoodsNode.active = true;
            this.noGoodsNode.getComponent(Label).string = "No Message.";
            return;
        }
        this.noGoodsNode.active = false;

        let preY = this.content2.position.y;
        let preH = this.content2.getComponent(UITransform).height;
        // this.content2.removeAllChildren();
        // this.content2.getComponent(UITransform).height = 0;
        // let childNum = this.content2.children.length;
        // let addChildNum = records.length - childNum;
        let records = this.bagInfo.records;
        for (let i = 0; i < records.length; ++i) {
            let record = records[i];
            let itemNode = this.content2.getChildByName(record.id.toString());
            if (itemNode) {
                // do nothing
                // let bagInfoItem = itemNode.getComponent(BagInfoItem);
                // bagInfoItem.setData(record, i);
            } else {
                ResManager.Instance().load("gamesCommon", "resources/prefabs/bag/BagInfoItem", Prefab, null, (data) => {
                    if (data && data.data && data.data instanceof Prefab) {
                        let itemNode = instantiate(data.data);
                        if (!itemNode) {
                            warn(`instantiate BagInfoItem node failed`);
                            return;
                        }
                        itemNode.name = record.id.toString();
                        let bagInfoItem = itemNode.getComponent(BagInfoItem);
                        bagInfoItem.setData(record, i);
                        this.content2.addChild(itemNode);
                    }
                    else {
                        warn(`load prefab : resources/prefabs/bag/BagInfoItem fail`);
                        return;
                    }
                });
            }
        }

        // this.scrollPosTimer = setTimeout(() => {
        //     if (!this || !this.content2) return;
        //     let curH = this.content2.getComponent(UITransform).height;
        //     let viewH = this.content2.parent.getComponent(UITransform).height;
        //     preH = preH > viewH ? preH : viewH;
        //     let shouldY = 0;
        //     if (curH <= viewH) {
        //         shouldY = 0;
        //     } else {
        //         shouldY = preY + (curH - preH);
        //     }

        //     this.content2.setPosition(0, shouldY);
        // }, 0);
    }

    private onTabClicked(index: number) {
        if (index == this.selIndex) return;
        // this.selIndex = index;
        switch (index) {
            case 0:
                GameComUtils.c2sStat(StatConst.OPEN_BAG_SCREEN);
                this.updateItems(0);
                break;
            case 1:
                GameComUtils.c2sStat(StatConst.OPEN_BAG_OTHER_GAME);
                this.updateItems(1);
                break;
            case 2:
                GameComUtils.c2sStat(StatConst.OPEN_BAG_USER_RECORD);
                this.updateMyInfo();
                break;
        }
    }

    public close() {
        clearTimeout(this.scrollPosTimer);
        super.close();
    }

}

