import { Global } from "../../../../../scripts/main/Global";

/**
 * @description 彩金语言包
 * @author guohuo
 */
export const WinningsLangConfig = {
    "tabNames": {
        "en": ["Must Hit By", "OtherGames"],
        "cn": ["Must Hit By", "OtherGames"]
    },
    "title": {
        "en": "BACKPAD",
        "cn": "背包"
    },
    "zhidingyazhu": {
        "en": "Designated Bets:",
        "cn": "指定押注"
    },
    "caichanxianzhi": {
        "en": "Limitation Of Estate:",
        "cn": "财产限制"
    },
    "shiyongqixian": {
        "en": "Availability Date：",
        "cn": "使用期限"
    },
    "scoreTitle": {
        "en": "COIN",
        "cn": "积分",
    },
    "scoreDesc": {
        "en": "Commonly used coin of the platform, will be accumulated to balance when obtained.",
        "cn": "平台通用积分，获得后会直接加到余额中",
    },
    "balanceLimit": {
        "en": "{0} {1} least",
        "cn": "{0} {1} 以上"
    },
    "balanceLimit2": {
        "en": "Can be used when balance reaches{0} {1}",
        "cn": "需要余额达到{0} {1}才能使用哦"
    },
    "tryLater": {
        "en": "please try later",
        "cn": "请稍后再试哦"
    },
    "useTimeBegin": {
        "en": "sorry, can't use now",
        "cn": "未到使用日期哦"
    },
    "useTimeEnd": {
        "en": "out of date",
        "cn": "过期不能使用哦",
    },
    "maxValue": {
        "en": "It's already the biggest",
        "cn": "已经是最大哦"
    },
    "minValue": {
        "en": "It's already the smallest",
        "cn": "已经是最小哦"
    },

    get: (key1: string, key2?: any) => {
        let lang = Global.language;
        if (!WinningsLangConfig[key1]) {
            return `key1:${key1} no cfg`;
        } else if (key2 && !WinningsLangConfig[key1][key2]) {
            return `key1:${key1}, key2:${key2} no cfg`;
        }

        if (!key2) {
            return WinningsLangConfig[key1][lang] || WinningsLangConfig[key1]["en"];
        } else {
            return WinningsLangConfig[key1][key2][lang] || WinningsLangConfig[key1][key2]["en"];
        }
    }
}
