export class UIGameDefined {
    static setUIComCF(gameId?: number): { [key: number]: UIConf } {
        if (!gameId)
            return UICF;

        UICF[UIID_GAME.UIChooseRoomType] = { prefab: "resources/prefabs/fishCommon/ChooseRoomTypePref", bundle: gameId.toString() };
        UICF[UIID_GAME.UIFishingHelp] = { prefab: "resources/prefabs/fishCommon/UIFishingHelpPref", bundle: gameId.toString() };

        return UICF;
    }
}