import { _decorator, Asset, SpriteFrame } from 'cc';
import { EGAME_TYPE, EOSID } from '../../../scripts/common/define/EnumDefine';
import { Entry } from '../../../scripts/framework/hall/entry/Entry';
import { EntryManager } from '../../../scripts/framework/hall/entry/EntryManager';
import { Resource } from '../../../scripts/framework/hall/Resource';
import { ResManager } from '../../../scripts/framework/manager/ResManager';
import { UIManager } from '../../../scripts/framework/ui/UIManager';
import { ScreenType } from '../../../scripts/framework/ui/UIView';
import { Global } from '../../../scripts/main/Global';
import { GameCommonManager } from './GameCommonManager';
import { GameCommonModel, ReportType } from './GameCommonModel';
import { GameLoadingView } from './gameLoading/GameLoadingView';
import GamesData from './GamesData';
import { BUNDLE_NAME, UICF, UIGameDefined, UIID_GAME } from './UIGameDefined';
import TimeUtil from '../../../scripts/common/utils/TimeUtil';

export class GameHallEntry extends Entry {

    static bundle = BUNDLE_NAME.gamesCommon;

    protected initData(): void {
        GamesData.init();
        GameCommonManager.getInstance().report(ReportType.entergame);

    }
    protected loadResources(completeCb: () => void): void {
        ResManager.Instance().loadRemoteImg(GamesData.getPosterByid(Global.gameId), true,
            (spriteFrame: SpriteFrame) => {
                this.showPoster(spriteFrame);
            });
        this.loader.getLoadResources = () => {
            return [{ dir: "resources", bundle: BUNDLE_NAME.gamesCommon, type: Asset }];
        };
        this.loader.onLoadProgress = this.onProgress.bind(this);
        this.loader.onLoadComplete = (code: Resource.LoaderError) => {
            if (code == Resource.LoaderError.SUCCESS) {
                completeCb();
            }
        }
        this.loader.loadResources();
    }

    protected openGameView(): void {
        GamesData.stopBgMusic();
        GameCommonManager.getInstance().registerMsgListener();
        GameCommonManager.getInstance().startTimeMark();

        this.loadCfg().then(this.enterBundle.bind(this));
    }

    private enterBundle() {
        console.log('==============enterBundle================');
        let gameType: EGAME_TYPE = GameCommonModel.getInstance().getGameTypeByGameId(GamesData.gameId);
        let bundleName = '';
        if (gameType == EGAME_TYPE.FISHING) {
            bundleName = BUNDLE_NAME.fishingCommon;
        }
        else if (gameType == EGAME_TYPE.SLOTS) {
            bundleName = BUNDLE_NAME.rollCommon;
        }
        else if (gameType == EGAME_TYPE.MO_GAME) {
            bundleName = BUNDLE_NAME.tableCommon;
        }
        else { //类型不存在
            console.error('==============bundleName================', bundleName);
        }

        UIGameDefined.setUIComCF(GamesData.gameId);

        if (bundleName != '')
            EntryManager.getInstance().enterBundle(bundleName);

        UIManager.getInstance().setUIConf(UICF);
        UIManager.getInstance().open(UIID_GAME.UIGameLoading);
        UIManager.getInstance().open(UIID_GAME.UIAniNotice);
    }

    private showPoster(img: SpriteFrame): void {
        if (!img) {
            return;
        }
        // let loadingView: GameLoadingView;
        // loadingView = UIManager.getInstance().getUI(UIID_GAME.UIGameLoading) as GameLoadingView;
        // if (!loadingView) {
        //     return;
        // }
        // if (loadingView.gamePosterNode) {
        //     loadingView.gamePosterNode.spriteFrame = img;
        // }
    }

    protected closeGameView(): void {
    }


    protected onProgress(current: number, total: number): void {
    }

    protected async loadCfg() {
        return new Promise((resolve, reject) => {
            GameCommonModel.getInstance().initGameCfg(() => {
                resolve(null);
            });
        });
    }
}
EntryManager.getInstance().register(GameHallEntry);