import { _decorator, Component, Sprite, SpriteFrame } from "cc";
const { ccclass, requireComponent } = _decorator;

/**
 * 序列帧动画播放
 */
@ccclass("FrameEffect")
@requireComponent(Sprite)
export class FrameEffect extends Component {
    protected _img: Sprite;
    protected _sources: SpriteFrame[];  //序列帧资源
    /**帧间隔 单位秒  相当于30fps */
    protected _frameTime = 1 / 30;

    protected _loops = 1;  //循环次数
    protected _curLoop = 0;  //当前循环次数

    protected _lastTime = 0;
    protected _frameIdx = 0;

    protected _eventList: FrameEvent[];
    protected _isPlaying = false;

    protected _callBack: Function;
    protected _caller: any;
    protected _args: any;

    /**
     * 初始化
     * @param fps 帧率
     */
    public init(fps: number) {
        this._img = this.node.getComponent(Sprite);
        this._sources = [];
        this._eventList = [];
        this._frameTime = 1 / fps;
    }

    /**
     * 添加帧事件
     * @param evt 事件
     * @returns 
     */
    public addEvent(evt: FrameEvent) {
        for (let temp of this._eventList) {
            if (temp.id == evt.id) {
                return false;
            }
        }
        this._eventList.push(evt);
        return true;
    }

    /**
     * 删除帧事件
     * @param id 事件id
     * @returns 
     */
    public deleteEvent(id: number) {
        for (let i = this._eventList.length - 1; i >= 0; i--) {
            let evt = this._eventList[i];
            if (evt.id == id) {
                this._eventList.splice(i, 1);
                return true;
            }
        }
        return false;
    }

    /**
     * 清除帧事件
     */
    public clearEvent() {
        this._eventList.length = 0;
    }

    /**
     * 添加帧序列
     * @param sources 序列帧资源
     * @param isReverse 是否逆序添加，默认false
     */
    public addFrame(sources: SpriteFrame[], isReverse = false) {
        if (sources) {
            let temp = sources.slice();
            if (isReverse) {
                temp.reverse();
            }
            this._sources.push(...temp);
        }
    }

    /**
     * 清除序列
     */
    public clearFrame() {
        this._sources.length = 0;
    }

    /**
     * 开始播放
     * @param startIndex 从第几帧开始播放 默认从第1帧开始
     * @param loops 循环次数 默认1次 <=0则无限循环
     * @param call 播放完成后回调
     * @param obj 回调对象
     */
    public paly(startIndex = 0, loops = 1, call?: Function, obj?: any, args?: any) {
        if (!this._sources || this._sources.length == 0) {
            return;
        }
        this._isPlaying = true;
        this._frameIdx = startIndex <= 0 ? 0 : startIndex;
        this._loops = loops;
        this._callBack = call;
        this._caller = obj;
        this._args = args;
        this._lastTime = this._frameTime + 1;  //确保立即播放第一帧
    }

    /**
     * 暂停播放
     */
    public pause() {
        this._isPlaying = false;
    }

    /**
     * 继续播放
     */
    public resume() {
        this._isPlaying = true;
    }

    /**
     * 重置循环次数
     */
    public resetLoopTimes() {
        this._curLoop = 0;
    }

    protected update(deltaTime: number) {
        if (!this._isPlaying) {
            return;
        }
        this._lastTime += deltaTime;
        if (this._lastTime >= this._frameTime) {
            this._lastTime -= this._frameTime;
            let frames = this._sources.length;
            this._frameIdx %= frames;
            this._img.spriteFrame = this._sources[this._frameIdx];
            for (let evt of this._eventList) {
                if (evt.index == this._frameIdx) {
                    evt.event();
                }
            }
            this._frameIdx++;
            if (this._frameIdx == frames) { //最后一帧
                if (this._loops > 0) {  //不循环播放
                    this._curLoop++;
                    if (this._curLoop >= this._loops) {  //最后一次循环结束
                        this.pause();
                        this._onComplete();
                    }
                }
            }
        }
    }

    private _onComplete() {
        if (this._callBack && this._caller) {
            this._callBack.call(this._caller, this._args);
        }
    }
}

export class FrameEvent {
    /**事件id */
    private _id: number;
    /**第几帧触发事件 */
    private _index: number;
    /**触发次数 <=0 不限次 */
    private _times: number;
    /**事件回调对象 */
    private _thisObj: any;
    /**事件回调方法 */
    private _callBack: Function;
    /**回调事件参数 */
    private _args: any[];

    /**当前触发次数 */
    private _curTimes = 0;

    public get id(): number {
        return this._id;
    }

    /**事件所在的帧 */
    public get index(): number {
        return this._index;
    }

    /**
     * 帧事件
     * @param id 事件id
     * @param index 触发事件的帧索引
     * @param times 触发次数  默认1次
     * @param thisObj 回调对象
     * @param call 回调函数
     * @param args 回调参数
     */
    public constructor(id: number, index: number, times = 0, thisObj?: any, call?: Function, ...args: any[]) {
        this._id = id;
        this._index = index;
        this._times = times;
        this._thisObj = thisObj;
        this._callBack = call;
        this._args = args;
        this._curTimes = 0;
    }

    /**触发事件 */
    public event() {
        if (this._times > 0) {
            this._curTimes++;
            if (this._curTimes <= this._times) {
                this._triggerEvent();
            }
        }
        else {
            this._triggerEvent();
        }
    }

    /**重置事件触发次数 */
    public resetTimes() {
        this._curTimes = 0;
    }

    /**触发事件 */
    private _triggerEvent() {
        if (!this._thisObj || !this._callBack) {
            return;
        }

        this._callBack.call(this._thisObj, ...this._args);
    }
}