import { _decorator, Sprite, ProgressBar, assetManager, Button, NodeEventType, Label, SpriteFrame, Node, UITransform, Prefab, instantiate } from 'cc';
import { SoundDefine } from '../../../../scripts/common/define/ResDefine';
import AudioManager from '../../../../scripts/framework/manager/AudioManager';
import { CacheManager } from '../../../../scripts/framework/manager/CacheManager';
import { ResManager } from '../../../../scripts/framework/manager/ResManager';
import { ScreenType, UIView } from '../../../../scripts/framework/ui/UIView';
import { Global } from '../../../../scripts/main/Global';
import { GameCommonManager } from '../GameCommonManager';
import GamesData from '../GamesData';
import { BUNDLE_NAME } from '../UIGameDefined';
import { Eventer } from '../../../../scripts/framework/Eventer';
import { Events } from '../../../../scripts/framework/Events';
import { EGAME_TYPE } from '../../../../scripts/common/define/EnumDefine';
import { GameConst } from '../../../../scripts/main/GameConst';
import { GameComUtils } from '../utils/GameComUtils';
const { ccclass, property } = _decorator;

@ccclass('GameLoadingView')
export class GameLoadingView extends UIView {

    @property(Sprite)
    gamePosterNode: Sprite = null;
    @property(Sprite)
    gameVerPosterNode: Sprite = null;
    @property(ProgressBar)
    progress: ProgressBar = null;
    @property(Sprite)
    bar: Sprite = null;
    @property(Sprite)
    pre: Sprite = null;
    @property(Label)
    txtProgress: Label = null;
    @property(Button)
    closeBtn: Button = null;
    @property(Node)
    light: Node = null;
    private _lightAni: Prefab;

    private _current: number;
    private _total: number;
    private _stop: boolean;

    init(...args): void {

        this._current = 0;
        this._total = 0;
        this._stop = false;
        this._timeMark = 0;
        this.progress.progress = 0;
        this.txtProgress.string = "";
        this.light.active = false;
        this.node.active = false;

        this.closeBtn.node.on(NodeEventType.TOUCH_END, this.onBack, this);
        this.initCloseBtn();
        this.addEvent();
    }

    start() {
        this.updateBg();
        this.updateLight();
        this.changeScreen();
    }

    private _timeMark: number = 0;
    update(deltaTime: number) {
        this._timeMark += deltaTime;
        if (this._timeMark < 0.1) {
            return;
        }
        if (!this._total) {
            return;
        }

        this._timeMark = 0;
        if (this._stop) {
            return;
        }
        let text = "";
        let rate: number = 0;
        if (this._total > 0) {
            rate = this._current / this._total;
        }
        if (rate < 0) {
            rate = 0;
        }
        if (rate > 1) {
            rate = 1;
        }
        this._stop = (Math.floor(this._current) == this._total);
        rate = Math.floor(rate * 100) / 100;
        if (rate != this.progress.progress) {
            this.progress.progress = rate;
        }

        text = Math.floor(rate * 100) + "%";// `${Math.floor(this._current)}/${this._total}`;
        if (text != this.txtProgress.string) {
            this.txtProgress.string = text;
        }

        this.updateLightPos();
    }

    private updateBg() {
        console.log("GamesData.getPosterByid(GamesData.gameId) ===", GamesData.gameId, GamesData.getPosterByid(GamesData.gameId));
        // ResManager.Instance().loadRemoteImg(GamesData.getPosterByid(GamesData.gameId), true,
        //     (spriteFrame: SpriteFrame) => {
        //         if (this.gamePosterNode && spriteFrame) {
        //             this.gamePosterNode.spriteFrame = spriteFrame;
        //         }
        //     });

        // if (GameConst.isHasVerLoading(Global.gameId))
            // ResManager.Instance().loadRemoteImg(GamesData.getVerPosterByid(GamesData.gameId), true,
            //     (spriteFrame: SpriteFrame) => {
            //         if (this.gameVerPosterNode && spriteFrame) {
            //             this.gameVerPosterNode.spriteFrame = spriteFrame;
            //         }
            //     });

        ResManager.Instance().load(BUNDLE_NAME.gamesCommon, `preload/loading/${GamesData.gameId}_bar/spriteFrame`, SpriteFrame, () => { }, (evt: any) => {
            let spriteFrame: SpriteFrame = evt.data;
            if (this.bar) {
                if (spriteFrame) {
                    this.bar.spriteFrame = spriteFrame;
                    this.bar.node.getComponent(UITransform).width = spriteFrame.rect.width;
                    this.bar.node.getComponent(UITransform).height = spriteFrame.rect.height;
                }
                this.bar.node.active = true;
            }
        });

        ResManager.Instance().load(BUNDLE_NAME.gamesCommon, `preload/loading/${GamesData.gameId}_pre/spriteFrame`, SpriteFrame, () => { }, (evt: any) => {
            let spriteFrame: SpriteFrame = evt.data;
            if (this.pre) {
                if (spriteFrame) {
                    this.pre.spriteFrame = spriteFrame;
                    let uicom = this.pre.node.getComponent(UITransform);
                    uicom.width = 0;
                    uicom.height = spriteFrame.rect.height;
                    this.pre.node.setPosition(-spriteFrame.rect.width / 2, 0);

                    this.updateLightPos();
                    this.progress.totalLength = spriteFrame.rect.width;
                    this.progress.progress = 0;
                }
                this.pre.node.active = true;
            }
        });
    }

    /** 刷新光标资源 */
    private updateLight() {
        let path = GameComUtils.progressBarColorPath();
        ResManager.Instance().load(BUNDLE_NAME.gamesCommon, path, Prefab, null, (cache) => {
            let pref: Prefab = <Prefab>cache.data;
            if (!pref)
                return;

            let itemNode = instantiate(pref);
            this.light.addChild(itemNode);
        })
    }

    private initCloseBtn() {
        if (Global.playback)
            this.closeBtn.node.active = false;
        if (Global.closeBack)
            this.closeBtn.node.active = false;
    }

    /**
     * onProgress 更新进度
     * @param current 当前进度
     * @param total 进度总数
     */
    public onProgress(current: number, total: number): void {
        this._current = current;
        this._total = total;
    }

    /**
     * 刷新闪光位置
     */
    private updateLightPos() {
        let x = this.pre.node.position.x + this.pre.node.getComponent(UITransform).width;
        this.light.active = true;
        this.light.setPosition(x, 4);
    }

    private onBack(evt) {
        if (Global.homeUrl) {
            Global.backHomeUrl();
            return;
        }

        AudioManager.Instance().playEffect(SoundDefine.sound_close);

        // if (GamesData.stopLoading) {
        //     GamesData.stopLoading();
        // }

        GameCommonManager.getInstance().backToHall();
        GameCommonManager.getInstance().releaseRec();
        // this.close();
    }

    private destorySpriteFrame(spriteFrame: SpriteFrame, url: string) {
        assetManager.releaseAsset(spriteFrame.texture);
        CacheManager.getInstance().remoteCaches.remove(url);

        while (spriteFrame.refCount > 0) {
            spriteFrame.decRef(true);
        }
        spriteFrame.destroy();
        assetManager.releaseAsset(spriteFrame);
        spriteFrame = null;
    }

    private changeScreen() {
        if (Global.gameType != EGAME_TYPE.SLOTS)
            return;

        if (GameConst.isHasVerLoading(Global.gameId))
            if (Global.gameScreenType == ScreenType.Portrait) {
                // this.progress.node.setPosition(555, 0);
                // this.progress.node.angle = 90;
                this.progress.node.setScale(0.8, 0.8);
                // this.closeBtn.node.setPosition(-566, 304);
                // this.closeBtn.node.angle = 90;
                this.gamePosterNode.node.active = false;
                this.gameVerPosterNode.node.active = true;
            } else {
                this.progress.node.setPosition(0, -300);
                this.progress.node.angle = 0;
                this.progress.node.setScale(1, 1);
                this.closeBtn.node.setPosition(587, 304);
                this.closeBtn.node.angle = 0;
                this.gamePosterNode.node.active = true;
                this.gameVerPosterNode.node.active = false;
            }
    }

    private logoPlayEnd() {
        this.node.active = true;
    }

    private addEvent() {
        Eventer.getInstance().on(Events.ScreenSwitchEvent, this.changeScreen, this);
        Eventer.getInstance().on(Events.LogoPlayEnd, this.logoPlayEnd, this);
    }

    protected onDestroy(): void {
        Eventer.getInstance().offName(Events.ScreenSwitchEvent, this);
        Eventer.getInstance().offName(Events.LogoPlayEnd, this);
    }

    /**
    * 当界面被关闭时回调，每次调用Close时回调
    * 返回值会传递给下一个界面
    */
    onClose(): any {
        Log.d("回收loading界面")

        this.gamePosterNode.node.destroy();
        this.gameVerPosterNode.node.destroy();
    }
}