import { _decorator, Component, Node } from 'cc';
import AudioManager from '../../../../scripts/framework/manager/AudioManager';
import { BUNDLE_NAME } from '../UIGameDefined';
const { ccclass, property } = _decorator;

@ccclass('GameResPath')
class GameResPath {

    /**
     * getRollCommonSound 获取滚轮通用库的声音路径
     * @param mName 声音名称
     * @returns string
     */
    public getRollCommonSound(mName:string):string {
        return `resources/sounds/${mName}`;
    }

    /**
     * 播放滚轮通用库的声音
     * @param mName 声音名称
     */
    public playRollCommonSound(mName:string):void
    {
        AudioManager.Instance().playEffect(this.getRollCommonSound(mName),BUNDLE_NAME.rollCommon);
    }
}
export default new GameResPath();

