import { _decorator, Component, Node, Sprite, AssetManager, Asset, SpriteFrame } from 'cc';
import { ResManager } from '../../../../scripts/framework/manager/ResManager';
import { McCfgVo } from '../GameCommonModel';
const { ccclass, property } = _decorator;

/**
 * 影片剪辑,绑定此组件的节点必须要有sprite，MovieClip主要是对该节点的sprite做处理
 * @author ice
 */
@ccclass('MovieClipComp')
export class MovieClipComp extends Component {

    @property({ displayName: "img", type: Sprite, tooltip: '需要控制的Sprite' })
    private img: Sprite;
    @property({ displayName: "hideForEnd", type: Boolean, tooltip: '播放停止后是否需要隐藏影片，默认：false' })
    public hideForEnd: boolean=false;

    /** 影片名称 */
    public mcName: string = "";
    /** 影片路径 */
    public mcPath: string;
    // public bundle: AssetManager.Bundle;
    /** 影片对应的bundle名称 */
    public bundleName: string;
    /** 总帧数, 必须赋值*/
    public totalFrame: number = 0;
    /** 间隔多少秒播下一帧(单位：秒) */
    public interval: number = 0;

    /** 起始帧，默认为0 */
    public startFrame: number = 0;
    /** 终结帧,默认0（播放到最后一帧）*/
    public endFrame: number = 0;
    /** 循环次数，默认死循环 */
    public loop: number = 0;
    /** 影片播放到最后一帧执行 */
    public mcEndCallBack: Function;
    /** 影片在指定循环次数完毕的时候执行 */
    public loopEndCallBack: Function;
    /** 参数：当前帧 */
    public enterFrameFun: Function;

    /** 是否在播放中 */
    private _isPlay: boolean = false;
    public get isPlay():boolean
    {
        return this._isPlay;
    }
    private _curTime: number;
    private _curFrame: number;
    private _curLoop: number;
    // private _mcCfg:McCfgVo;
    // public get mcCfg():McCfgVo
    // {
    //     return this._mcCfg;
    // }

    protected __preload(): void {
        if (!this.img) {
            Log.e("mc no sprite!!");
        }
        this._curTime = 0;
        this._curFrame = this.startFrame;
        this._curLoop = 0;
        // this.updataSp();
    }

    // start() {}

    update(deltaTime: number) {
        if (this._isPlay == false) {
            return;
        }

        this._curTime += deltaTime;
        if (this._curTime < this.interval) {
            return;
        }
        this._curTime -= this.interval;

        if (!this.totalFrame) {
            Log.e("影片：" + this.mcPath + " 的totalFrame未赋值");
        }
        if (this.endFrame <= 0) {
            this.endFrame = this.totalFrame - 1;
        }
        if (this._curFrame >= this.endFrame) {
            if (this.loop > 0) {
                this._curLoop++;
                if (this._curLoop >= this.loop) {
                    this._isPlay = false;
                    if(this.hideForEnd==true)
                    {
                        this.node.active=false;
                    }
                    if (this.loopEndCallBack) {
                        this.loopEndCallBack();
                    }
                    return;
                }
            }
            this._curFrame = this.startFrame;
        }
        else {
            this._curFrame++;
        }

        if (this._curFrame == this.endFrame) {
            if (this.mcEndCallBack) {
                this.mcEndCallBack();
            }
        }

        if (this.enterFrameFun) {
            this.enterFrameFun(this._curFrame);
        }

        this.updataSp();
    }

    public updataCfg(cfg: McCfgVo): void {
        // this._mcCfg=cfg;
        if (cfg.mcName) {
            this.mcName = cfg.mcName;
        }
        if (cfg.mcPath) {
            this.mcPath = cfg.mcPath;
        }
        if (cfg.bundleName) {
            this.bundleName = cfg.bundleName;
        }
        if (cfg.startFrame) {
            this.startFrame = cfg.startFrame;
            if (!this._curFrame || this._curFrame < this.startFrame) {
                this._curFrame = this.startFrame;
            }
        }
        if (cfg.totalFrame) {
            this.totalFrame = cfg.totalFrame;
        }
        if (cfg.loop) {
            this.loop = cfg.loop;
        }
        if (cfg.interval) {
            this.interval = cfg.interval;
        }
    }

    public play() {
        this._isPlay = true;
    }

    public stop(): void {
        this._isPlay = false;
    }

    public gotoAndPlay(mFrame: number): void {
        if (mFrame < this.startFrame) {
            mFrame = this.startFrame;
        }
        if (mFrame >= this.totalFrame) {
            mFrame = this.totalFrame - 1;
        }
        this._curFrame = mFrame;
        this.updataSp();
        this._isPlay = true;
    }

    public gotoAndStop(mFrame: number): void {
        this._isPlay = false;
        if (mFrame < this.startFrame) {
            mFrame = this.startFrame;
        }
        if (mFrame >= this.totalFrame) {
            mFrame = this.totalFrame - 1;
        }
        this._curFrame = mFrame;
        this.updataSp();
    }

    /**
     * 重播
     * @param mFrame 第几帧开始重播
     */
    public rePlay(mFrame: number = 0): void {
        this.rePos(mFrame);
        this._isPlay = true;
    }

    /** 重置 */
    public rePos(mFrame: number = 0): void {
        this._curFrame = mFrame>=this.startFrame ? mFrame:this.startFrame;
        this._curTime = 0;
        this._curLoop = 0;
        this.updataSp();
    }

    public updataSp() {
        if (!this.img) {
            Log.e("mc no sprite!!");
        }
        let mURL: string = this.mcPath + "/" + this.mcName + this._curFrame + "/spriteFrame";
        ResManager.Instance().load(this.bundleName, mURL, SpriteFrame, () => { }, (evt: any) => {
            this.img.spriteFrame = evt.data;
        });
    }
}

