import { log } from "cc";
import { Global } from "../../../../../scripts/main/Global";
import { GameToolsFunc } from "../task/GameToolsFunc";
import { Singleton } from "../../../../../scripts/framework/Singleton";
import { GameProtocolId } from "../../gameSocket/GameProtocolId";
import GameSocketManager, { C2S_ProtocolParams, S2C_ProtocolParams } from "../../gameSocket/GameSocketManager";
import { Eventer } from "../../../../../scripts/framework/Eventer";
import { GameEventType } from "../../GameEventType";
import { HttpMethod } from "../../../../../scripts/common/define/EnumDefine";
import { HttpMgr } from "../../../../../scripts/common/net/http/HttpMgr";
import { HttpReqPack } from "../../../../../scripts/common/net/http/HttpReqPack";
import GameHttpData from "../../GameHttpData";
import { HttpRespPack } from "../../../../../scripts/common/net/http/HttpRespPack";
import { GameData } from "../../../../../scripts/framework/hall/data/GameData";
import GamesData from "../../GamesData";
import WebMsgHandler from "../../../../../scripts/common/net/http/WebMsgHandler";

export class VipMgr extends Singleton<VipMgr>() {
    private gameSocketMgr: GameSocketManager;

    /** 
     * 我的vip数据
     *  required int: vipId // VIP主键
        required int: playerId // 玩家id
        required string: remark // VIP备注
        required string: lastActiveTime // VIP玩家最后活跃时间
        required int: growthValue // 玩家成长值
        required int: level // VIP等级	
        required int: gender // 性别, 0：未设置，1：男，2：女
        required string: birth // 出生日期
        required int: aid // 玩家对应代理ID
        required string: name // VIP名称
     */
    public vipData: any;

    /**
     * 所有vip配置
     * level	number	等级	
     * value	number	成长值	
     * reward	number  分数奖励	
     * props	string	道具奖励 json格式："[{\"prop_id\":\"38\",\"prop_type\":\"0\",\"game_id\":\"3000003\",\"num\":\"5\"}]"
     *                                      注意这个格式解析出来的prop_id为字符串，其他一样
     */
    public vipCfgs: any[];
    // [
    //     // { level: 1, value: 100, reward: 100 },
    //     { level: 2, value: 200, reward: 200 },
    //     { level: 3, value: 300, reward: 300 },
    //     { level: 5, value: 500, reward: 500 },
    //     { level: 6, value: 600, reward: 600 },
    // ];

    /**
     * vip规则描述
     * coin	number	金币/次	
     * valAdd	number	增加成长值	
     * days	number	连续不活跃天数	
     * valSub	number	减少成长值	
     * valRule	string	成长值规则	
     * vipRule	string	会员等级说明
     */
    public vipRules: any;

    constructor() {
        super();
        this.gameSocketMgr = GameSocketManager.getInstance();
        this.registerMsgListener();
    }

    public registerMsgListener() {
        this.gameSocketMgr.registerMsgListener<S2C_ProtocolParams>(GameProtocolId.vip_detail, this.s2cVipDetail, this);
    }


    public c2sVipDetail() {
        // Log.e("c2sVipDetail");
        let cts: C2S_ProtocolParams<any> = {
            type: GameProtocolId.vip_detail,
            message: null,
        }
        GameSocketManager.getInstance().sendMessage<C2S_ProtocolParams>(GameProtocolId.vip_detail, cts);
    }
    private s2cVipDetail(msg: S2C_ProtocolParams<any>) {
        // Log.e("s2cVipDetail:", msg);
        if (!msg.succ) return;

        this.vipData = msg.message[0] || { growthValue: 0, level: 0 };

        Eventer.getInstance().emit(GameEventType.vip_detail, msg.message);
    }

    public c2sVipAllCfgs() {
        // Log.e("c2sVipAllCfgs");
        let pack: HttpReqPack = HttpReqPack.create("/api/vip/fetchVipRank", `?uid=${WebMsgHandler.webSrc.uid}`, HttpMethod.GET);
        HttpMgr.Instance().send(pack, null, this.s2cVipAllCfgs.bind(this));
    }
    private s2cVipAllCfgs(msg: HttpRespPack) {
        // Log.e("s2cVipAllCfgs:", msg);
        if (msg && msg.code == 200) {
            this.vipCfgs = msg.data;
            Eventer.getInstance().emit(GameEventType.vip_all_cfg);
        }
    }

    public c2sVipRules(data?: any) {
        // Log.e("c2sVipRules");
        let pack: HttpReqPack = HttpReqPack.create("/api/vip/fetchVipRule", `?uid=${WebMsgHandler.webSrc.uid}`, HttpMethod.GET);
        HttpMgr.Instance().send(pack, data, this.s2cVipRules.bind(this));
    }
    private s2cVipRules(msg: HttpRespPack, data: any) {
        // Log.e("s2cVipRules:", msg);
        if (msg && msg.code == 200) {
            this.vipRules = msg.data;
            Eventer.getInstance().emit(GameEventType.vip_rule);
            if (data && typeof data == 'function') data();
        }
    }
}