import { _decorator, Node, view, sys, Vec3, screen, Size } from 'cc';
import { EOSID } from '../../../scripts/common/define/EnumDefine';
import { UIManager } from '../../../scripts/framework/ui/UIManager';
import { Global } from '../../../scripts/main/Global';
import SdkManager from '../../../scripts/common/sdk/SdkManager';
import { GameUtils } from '../../../scripts/common/utils/GameUtil';
import { ScreenType } from '../../../scripts/framework/ui/UIView';
import { DEBUG } from 'cc/env';
const { ccclass, property } = _decorator;

@ccclass('GameAdapter')
export class GameAdapter {

    private _onResize: (evt: Event) => void;
    private _timerId: number;

    /** 开始适配 */
    start() {
        this.startBrowserAdapt();
    }

    /** 删除适配 */
    onDestroy() {
        this.endBrowserAdapt();
    }

    private resize(): void {

        let designSize: Size = view.getDesignResolutionSize();
        let mainNode: Node = UIManager.getInstance().uiLayer.node;
        let scaleV3: Vec3 = mainNode.scale;
        var mode = GameUtils.getScreensMode();
        var scale = 1;

        let designRatio = 0;
        let screenRatio = 0;

        let screenW = screen.windowSize.width; //实际宽
        let screenH = screen.windowSize.height; //实际高

        let designW = designSize.width;
        let designH = designSize.height;

        Log.w('Global.osid:', Global.osid);
        Log.w('mode:', mode);
        if (DEBUG) {
            if (Global.osid == EOSID.PC) {
                Global.camera.node.angle = 0;
                let maxLength = Math.max(designH, designW);
                let minLength = Math.min(designH, designW);
                let lengthRotio = maxLength / minLength;
                designRatio = designW / designH;
                screenRatio = screenW / screenH;
                Log.w('lengthRotio:', lengthRotio);
                Log.w('designRatio:', designRatio);
                if (lengthRotio >= designRatio) {
                    scale = Math.min(lengthRotio, 1.78) / designRatio;
                } else {
                    scale = maxLength / designW / view.getScaleX();
                }
            } else {
                Log.w('SdkManager.isiPad:', SdkManager.isiPad);
                if (SdkManager.isiPad) {
                    if (mode == ScreenType.Portrait) {
                        //竖屏
                        Global.camera.node.angle = 90;
                        designRatio = designW / designH;
                        screenRatio = screenW / screenH;
                    } else {
                        //横屏
                        Global.camera.node.angle = 0;
                        designRatio = designH / designW;
                        screenRatio = screenH / screenW;
                    }
                } else {
                    if (mode == ScreenType.Portrait) {
                        //竖屏
                        Global.camera.node.angle = 90;
                        designRatio = designH / designW;
                        screenRatio = screenW / screenH;
                        Log.w('screenW:', screenW);
                        Log.w('screenH:', screenH);
                        scale = screenW / screenH;
                        Log.w('scale:', scale);
                    } else {
                        //横屏
                        Global.camera.node.angle = 0;
                        designRatio = designH / designW;
                        screenRatio = screenH / screenW;
                        if (screenRatio > designRatio) {
                            Log.w('screenW:', screenW);
                            Log.w('designSize.width:', designSize.width);
                            scale = screenW / designSize.width / view.getScaleX();
                        } else {
                            scale = 1;
                        }
                        Log.w('scale:', scale);
                    }
                }
            }
        } else {
            scale = 1;
        }
        Log.w('=====================');
        scaleV3.set(scale, scale, 1);
        mainNode.scale = scaleV3;
    }

    /**
     * 浏览器适配
     */
    protected startBrowserAdapt(): void {
        this._onResize = this.onResize.bind(this);
        window.addEventListener("resize", this._onResize);
        this.onResize(null);
    }

    private onResize(evt: Event): void {
        clearTimeout(this._timerId);
        this._timerId = setTimeout(() => {
            this.resize();
        }, 50);
    }

    /**
     * 恢复状态
     */
    private endBrowserAdapt(): void {
        clearTimeout(this._timerId);
        window.removeEventListener("resize", this._onResize);

        let mainNode: Node = UIManager.getInstance().uiLayer.node;
        let scaleV3: Vec3 = mainNode.scale;
        scaleV3.set(1, 1, 1);
        mainNode.scale = scaleV3;
    }

    /** 屏幕宽 */
    private get screenW(): number {
        if (DEBUG) {
            if (sys.isNative) {
                return screen.windowSize.width;
            } else if (sys.isBrowser) {
                return document.body.clientWidth;
            }
        }
        else {
            return screen.windowSize.width;
        }

        // if (sys.isMobile) {
        //     return Math.max(screen.windowSize.width, screen.windowSize.height);
        // } else {
        //     return screen.windowSize.width;
        // }
    }
    /** 屏幕高 */
    private get screenH(): number {
        if (DEBUG) {
            if (sys.isNative) {
                return screen.windowSize.height;
            } else if (sys.isBrowser) {
                return document.body.clientHeight;
            }
        }
        else {
            return screen.windowSize.height;
        }

        // if (sys.isMobile) {
        //     return Math.min(screen.windowSize.width, screen.windowSize.height);
        // } else {
        //     return screen.windowSize.height;
        // }
    }
}

