import { _decorator, Component, Node, Label, Sprite, Color, SpriteFrame } from 'cc';
import { Eventer } from '../../../../scripts/framework/Eventer';
import GameColorUtil from '../../../gamesCommon/script/GameColorUtil';
import { GameCommonModel } from '../../../gamesCommon/script/GameCommonModel';
import { GameEventType } from '../GameEventType';
const { ccclass, property } = _decorator;

@ccclass('NetstatView')
export class NetstatView extends Component {
    @property(Sprite)
    private wifiBitmap: Sprite;
    @property(Label)
    private wifiTextField: Label;

    @property(SpriteFrame)
    private wifi_fast: SpriteFrame;
    @property(SpriteFrame)
    private wifi_normal: SpriteFrame;
    @property(SpriteFrame)
    private wifi_slow: SpriteFrame;

    public constructor() {
        super();
        Log.d("NetstatView constructor");
    }

    start() {
        this.init();
        Log.d("NetstatView start");
        this.addToStage();
    }

    protected onDestroy(): void {
        Log.d("NetstatView onDestroy");
        this.wifiBitmap=null;
        this.wifiTextField=null;
        this.wifi_fast=null;
        this.wifi_normal=null;
        this.wifi_slow=null;
        this.removeFromStage();
    }

    private init() {
        this.wifiTextField.string = '0ms';
        this.wifiTextField.color = GameColorUtil.green;
    }

    private refresh(time: number) {
        if(!this.wifi_fast)
        {
            return;
        }
        if (time < 0) {
            time = 0;
        } else if (time > 460) {
            time = 460;
        }

        if (time < 90) {
            this.wifiBitmap.spriteFrame = this.wifi_fast;
            this.wifiTextField.color = GameColorUtil.green;
        } else if (time < 150) {
            this.wifiBitmap.spriteFrame = this.wifi_normal;
            this.wifiTextField.color = GameColorUtil.yellow;
        } else {
            this.wifiBitmap.spriteFrame = this.wifi_slow;
            this.wifiTextField.color = GameColorUtil.red;
        }
        this.wifiTextField.string = time + 'ms';
    }

    private onHeartBeat(evtData: number): void {
        this.refresh(GameCommonModel.getInstance().intervalTime);
    }

    protected addToStage() {
        Eventer.getInstance().on(GameEventType.OnHeart, this.onHeartBeat, this);
    }

    protected removeFromStage() {
        Eventer.getInstance().offName(GameEventType.OnHeart, this);
    }
}

