import { Asset, ImageAsset, Node, UITransform, View, WebView, _decorator, sys } from "cc";
import { EGAME_TYPE } from "../../../../scripts/common/define/EnumDefine";
import { ResManager } from "../../../../scripts/framework/manager/ResManager";
import { UIButton } from "../../../../scripts/framework/ui/basic_ui/UIButton";
import { UIManager } from "../../../../scripts/framework/ui/UIManager";
import { ScreenType, UIView, UIZIndex } from "../../../../scripts/framework/ui/UIView";
import { Global } from "../../../../scripts/main/Global";
import { BUNDLE_NAME, UIID_GAME } from "../UIGameDefined";
import PlatformApi from "../../../../scripts/common/sdk/PlatformApi";
import SdkManager from "../../../../scripts/common/sdk/SdkManager";
import GamesData from "../GamesData";
import { Eventer } from "../../../../scripts/framework/Eventer";
import { Events } from "../../../../scripts/framework/Events";
import { CustomEventMgr } from "../../../../scripts/mgr/CustomEventMgr";
import { EventType } from "../../../../scripts/common/define/EventDefine";
import { GameCtrl } from "../../../../scripts/main/GameCtrl";
import AudioManager from "../../../../scripts/framework/manager/AudioManager";
const { ccclass, property } = _decorator;

@ccclass('RecordView')
export class RecordView extends UIView {

    @property(Node)
    public mask: Node;
    @property({
        displayName: '横屏',
        type: WebView
    })
    public webView1: WebView;
    @property({
        displayName: '竖屏',
        type: WebView
    })
    public divCloseBtn: HTMLButtonElement;

    start() {
        this.node.zIndex = UIZIndex.record;

        this.initEvent();
        this.initUrl();
    }

    private initEvent() {
        this.mask.on(Node.EventType.TOUCH_START, this.onCloseClick);

        CustomEventMgr.on(EventType.WEB_CLOSE_RECORD_VIEW, this.closeRecordView, this);
        CustomEventMgr.on(EventType.WEB_LOADED, this.loaded, this);

        Eventer.getInstance().on(Events.ScreenSwitchEvent, this.changeScreen, this);
    }

    private offEvent() {
        this.mask && this.mask.off(Node.EventType.TOUCH_START, this.onCloseClick);

        CustomEventMgr.off(EventType.WEB_CLOSE_RECORD_VIEW, this.closeRecordView, this);
        CustomEventMgr.off(EventType.WEB_LOADED, this.loaded, this);

        Eventer.getInstance().offName(Events.ScreenSwitchEvent, this);
    }

    private changeScreen() {
        var iframe = document.getElementById('iframe-record') as HTMLIFrameElement;
        if (!iframe) {
            console.warn('The record iframe cant found')
            return;
        }

        let screen = this.screenType;
        let params = {
            type: 'resize',
            value: screen
        }
        if (iframe.contentWindow)
            iframe.contentWindow.postMessage(JSON.stringify(params), '*');

        this.resetDivSize();
    }

    private closeRecordView() {
        this.removeDiv();
        Global.gameCtrl.webMusicSwitch = 1;
        AudioManager.Instance().setMusicEnabled();
        this.close();
    }

    private loaded() {
        this.changeScreen();
    }

    private initBtn() {
        if (this.divCloseBtn)
            return;

        var main = document.getElementById('webview-record');

        this.divCloseBtn = document.createElement('button');
        this.divCloseBtn.style.position = "absolute"
        if (this.screenType == ScreenType.Landscape) {
            this.divCloseBtn.style.right = "-22px";
            this.divCloseBtn.style.top = "-22px";
        } else {
            this.divCloseBtn.style.left = "-22px";
            this.divCloseBtn.style.top = "-22px";
        }
        this.divCloseBtn.style.width = "45px"
        this.divCloseBtn.style.height = "45px"
        this.divCloseBtn.style.zIndex = "10"
        this.divCloseBtn.style.backgroundColor = "transparent";
        this.divCloseBtn.style.borderColor = "transparent";
        this.divCloseBtn.style.borderStyle = "none";
        this.divCloseBtn.onclick = this.onCloseClick.bind(this);
        main.appendChild(this.divCloseBtn);

        let path = `resources/texture/gameCommonRec/gameCommonAtlas/close2`;
        ResManager.Instance().load(BUNDLE_NAME.gamesCommon, path, Asset, () => { }, (evt: any) => {
            let data: ImageAsset = evt.data;
            // let url = assetManager.utils.getUrlWithUuid(data._uuid);
            this.divCloseBtn.style.backgroundImage = `url(${data.nativeUrl})`;
        });
    }

    private initUrl() {
        let designWidth = View.instance.getDesignResolutionSize().width;
        let designHeigth = View.instance.getDesignResolutionSize().height;
        let screenWidth = 0, screenHeigth = 0;
        let styleScale = '90%';
        if (sys.isMobile) {
            screenWidth = View.instance.getViewportRect().width / 2;
            screenHeigth = View.instance.getViewportRect().height / 2;
            styleScale = '95%'
        } else {
            if (SdkManager.isiPad || SdkManager.isMac) {
                screenWidth = View.instance.getViewportRect().width / 2;
                screenHeigth = View.instance.getViewportRect().height / 2;
            } else {
                screenWidth = View.instance.getViewportRect().width;
                screenHeigth = View.instance.getViewportRect().height;
            }
            styleScale = '90%'
        }
        let screen = 1;
        if (this.screenType == ScreenType.Landscape) {
            screen = 1;
        } else {
            screen = 2;
        }

        var main = document.createElement("div");
        main.style.top = "50%";
        main.style.left = "50%";
        // main.style.width = `${screenWidth / (designWidth / this.webSize1)}px`;
        // main.style.height = `${screenHeigth / (designHeigth / this.webSize2)}px`;

        main.style.visibility = "visible";
        main.style.border = "none";
        main.style.position = "absolute";
        main.id = "webview-record";
        var cont = document.getElementById("Cocos3dGameContainer");
        cont.appendChild(main);
        this.resetDivSize();

        let token = Global.token;
        let gameId = Global.gameType == EGAME_TYPE.FISHING ? GamesData.gameId + GamesData.fishRoomId : Global.gameId;
        let src = Global.gameType == EGAME_TYPE.FISHING ? 'catch-fish' : 'contact-roller';
        var myIframe = document.createElement("iframe");
        // myIframe.width = `${width}px`;
        // myIframe.height = `${height}px`;
        myIframe.width = "100%";
        myIframe.height = "100%";
        myIframe.id = "iframe-record";
        myIframe.name = "iframe-record";
        myIframe.style.position = "absolute";
        myIframe.style.top = "50%";
        myIframe.style.left = "50%";
        myIframe.style.transform = "translate(-50%, -50%) rotate(0deg)";//this.screenType == ScreenType.Landscape ? "translate(-50%, -50%) rotate(0deg)" : "translate(-50%, -50%) rotate(-90deg)";
        myIframe.src = `${Global.gbsSvr}/game-record/#/${src}?token=${token}&gameId=${gameId}&screen=${screen}&lang=${Global.language}&fishResourcesId=${GamesData.gameId}&currency=${Global.currency}`;
        myIframe.style.border = "none";
        main.appendChild(myIframe);
    }

    private resetDivSize() {
        let divWidth = '0';
        let divHeight = '0';
        let styleScale = '90%';
        let angle = 0;
        var main = document.getElementById("webview-record");
        if (!main)
            return;

        if (sys.isMobile)
            styleScale = '95%';
        else
            styleScale = '90%';
        if (this.screenType == ScreenType.Landscape) {
            divWidth = styleScale;
            divHeight = styleScale;
            angle = 0;
        } else {
            divWidth = '95vw'
            divHeight = '95vh'
            angle = 270;
        }
        main.style.width = divWidth;
        main.style.height = divHeight;
        main.style.transform = `translate(-50%, -50%) rotate(${angle}deg)`;
    }

    private get screenType(): string {
        let status = 'landscape'
        if (window.matchMedia('(orientation: portrait)').matches) {
            status = 'portrait'
        }
        return status;
    }

    private onCloseClick() {
        UIManager.getInstance().closeToUI(UIID_GAME.UIRecord);
        document.getElementById("webview-record").remove();
        Global.gameCtrl.webMusicSwitch = 1;
        AudioManager.Instance().setMusicEnabled();
    }

    private removeDiv() {
        var cont = document.getElementById("Cocos3dGameContainer");
        var main = document.getElementById("webview-record");
        if (!main)
            return;
        cont.removeChild(main);

        this.offEvent();
    }

    protected onDestroy(): void {
    }
}