/**
 * @description 道具详情界面
 * @author guohuo
 */
import { _decorator, find, Node, Sprite, SpriteFrame, PageView, Component, ToggleContainer, instantiate, Toggle, Label } from 'cc';
import { GameUtils } from '../../../../../scripts/common/utils/GameUtil';
import { Eventer } from '../../../../../scripts/framework/Eventer';
import { UIManager } from '../../../../../scripts/framework/ui/UIManager';
import { ScreenType, UIView, UIZIndex } from '../../../../../scripts/framework/ui/UIView';
import { UIButton } from '../../../../../scripts/framework/ui/basic_ui/UIButton';
import { Global } from '../../../../../scripts/main/Global';
import ComponentMgr from '../../../../../scripts/mgr/ComponentMgr';
import { GameCommonManager } from '../../GameCommonManager';
import { GameCommonModel } from '../../GameCommonModel';
import { GameEventType } from '../../GameEventType';
import { UIID_GAME } from '../../UIGameDefined';
import { BagItem } from './BagItem';
import { ItemVo, BagModel, ItemType } from './BagModel';
import { ComTipsDlg, ComTipsDlgArgs } from '../common/ComTipsDlg';
import { GameComUtils } from '../../utils/GameComUtils';
import { GameToolsFunc } from '../task/GameToolsFunc';
import { BagLangConfig } from './BagLangConfig';
import StringUtil from '../../../../../scripts/common/utils/StringUtil';
import GamesData from '../../GamesData';
import { StatConst } from '../../stat/StatConst';
import { EGAME_TYPE } from '../../../../../scripts/common/define/EnumDefine';
import TimeUtil from '../../../../../scripts/common/utils/TimeUtil';
import { CurrencyUtil } from '../../../../../scripts/common/utils/CurrencyUtil';
const { ccclass, property } = _decorator;

@ccclass('ItemDetailDlg')
export class ItemDetailDlg extends UIView {

    @property({ type: Label, visible: true })
    private title: Label;
    @property({ type: BagItem, visible: true })
    private item: BagItem;
    @property({ type: Label, visible: true })
    private lab10: Label;
    @property({ type: Label, visible: true })
    private lab11: Label;
    @property({ type: Label, visible: true })
    private lab20: Label;
    @property({ type: Label, visible: true })
    private lab21: Label;
    @property({ type: Label, visible: true })
    private lab30: Label;
    @property({ type: Label, visible: true })
    private lab31: Label;
    @property({ type: Label, visible: true })
    private info: Label;

    @property({ type: Node, visible: true })
    private useGrp: Node;
    @property({ type: UIButton, visible: true })
    private addBtn: UIButton;
    @property({ type: UIButton, visible: true })
    private subBtn: UIButton;
    @property({ type: Label, visible: true })
    private num: Label;
    @property({ type: UIButton, visible: true })
    private useBtn: UIButton;
    @property({ type: UIButton, visible: true })
    private jumpBtn: UIButton;

    @property({ type: UIButton, visible: true })
    private closeBtn: UIButton;

    @property(Node)
    public nodeMask: Node;
    @property(Node)
    public panel: Node;

    private itemVo: ItemVo;
    private thisGame: boolean;

    init(...args): void {
        this.node.zIndex = UIZIndex.actUI;
    }

    start() {
        Eventer.getInstance().on(GameEventType.ScreenSwitch, this.onScreenSwitch, this);
    }

    public onOpen(itemVo: ItemVo) {
        this.itemVo = itemVo;
        this.addEvents();
        this.updateView();
        this.onScreenSwitch();
    }

    public onDestroy() {
        Eventer.getInstance().offName(GameEventType.act_item_info, this);
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
    }

    private onScreenSwitch(): void {
        if (Global.gameScreenType == ScreenType.Landscape) {
            this.panel.angle = 0;
            this.panel.setScale(1, 1);
        } else {
            this.panel.angle = 90;
            this.panel.setScale(0.8, 0.8); // 先不用panel_v..
        }
    }

    private addEvents() {
        this.closeBtn.touchEndedFun = this.onCloseClicked.bind(this);
        this.subBtn.touchEndedFun = this.onSubClicked.bind(this);
        this.addBtn.touchEndedFun = this.onAddClicked.bind(this);
        this.useBtn.touchEndedFun = this.onUseClicked.bind(this);
        this.jumpBtn.touchEndedFun = this.onJumpClicked.bind(this);


        Eventer.getInstance().on(GameEventType.act_item_info, this.onItemInfo, this);
    }

    private onItemInfo() {
        this.updateView();
    }

    private updateView() {
        let itemVo = this.itemVo;
        this.useGrp.active = this.jumpBtn.node.active = false;

        if (itemVo.propType == ItemType.Score) {
            this.title.string = BagLangConfig.get("scoreTitle");
            this.info.string = BagLangConfig.get("scoreDesc");
            this.item.setEasyData(0, ItemType.Score, itemVo.num, true);
            this.lab10.node.active = this.lab11.node.active = false;
            this.lab20.node.active = this.lab21.node.active = false;
            this.lab30.node.active = this.lab31.node.active = false;
            return;
        }

        let itemCfg = BagModel.getInstance().getItemCfg(itemVo.propId, itemVo.propType);
        let propName = itemCfg ? itemCfg.propName : "UNKNOWN";
        this.title.string = propName;
        this.item.setData(itemVo, true);
        this.num.string = "1";

        if (itemVo.isInBag) {
            let thisGame = itemVo.gameIds.indexOf(Global.gameId) != -1;
            this.thisGame = thisGame;
            if (thisGame) {
                this.useGrp.active = true;
            } else {
                this.jumpBtn.node.active = true;

                this.lab10.node.active = this.lab11.node.active = false;
                this.lab20.node.active = this.lab21.node.active = false;
                this.lab30.node.setPosition(-240, 92);
                this.lab31.node.setPosition(-43, 92);
            }
        }

        if (!itemCfg || !itemCfg.isHasDetailData) {
            this.lab11.string = '---';
            this.lab21.string = '---';
            this.lab31.string = '---';
            this.info.string = '---';
            GameCommonManager.getInstance().c2sActItemInfo(itemCfg.propId, itemCfg.propType);
        } else {
            if (!itemCfg.isShowBet) {
                this.lab10.node.active = this.lab11.node.active = false;
            }

            let curBet = itemCfg.bet;
            let line = GameCommonModel.getInstance().curBetLine;
            let bet = curBet * line * GameCommonModel.getInstance().betRate;
            let score = GamesData.formatScore(bet, false);
            this.lab11.string = score;
            this.lab21.string = StringUtil.formatString(BagLangConfig.get("balanceLimit"), CurrencyUtil.currencySymbol(itemCfg.currency), GamesData.formatScore(itemCfg.balanceLimit, false));
            if (!itemVo.useTimeBegin || !itemVo.useTimeEnd) {
                this.lab30.node.active = this.lab31.node.active = false;
            } else {
                this.lab30.node.active = this.lab31.node.active = true;
                this.lab31.string = TimeUtil.timeStamp2String(itemVo.useTimeBegin) + '-' + TimeUtil.timeStamp2String(itemVo.useTimeEnd);
            }
            this.info.string = itemCfg.propDesc;
        }

    }

    onSubOrAddNum(add: number) {
        let curNum = Number(this.num.string);
        curNum += add;
        let maxNum = this.itemVo.num;
        let minNum = 1;

        if (curNum < minNum) {
            curNum = minNum;
            ComponentMgr.showTips(BagLangConfig.get("minValue"));
        } else if (curNum > maxNum) {
            curNum = maxNum;
            ComponentMgr.showTips(BagLangConfig.get("maxValue"));
        }

        this.num.string = curNum.toString();
    }

    onSubClicked() {
        this.onSubOrAddNum(-1);
    }

    onAddClicked() {
        this.onSubOrAddNum(1);
    }

    onUseClicked() {
        let itemCfg = BagModel.getInstance().getItemCfg(this.itemVo.propId, this.itemVo.propType);
        if (itemCfg.balanceLimit) {
            if (itemCfg.balanceLimit > GameCommonModel.getInstance().money) {
                ComponentMgr.showTips(StringUtil.formatString(BagLangConfig.get("balanceLimit2"), CurrencyUtil.currencySymbol(itemCfg.currency), GamesData.formatScore(itemCfg.balanceLimit)));
                return;
            }
        }

        let serverTime = Global.svrTimeMS;
        if (this.itemVo.useTimeBegin && serverTime < this.itemVo.useTimeBegin) {
            ComponentMgr.showTips(BagLangConfig.get("useTimeBegin"));
            return;
        }
        if (this.itemVo.useTimeEnd && serverTime > this.itemVo.useTimeEnd) {
            ComponentMgr.showTips(BagLangConfig.get("useTimeEnd"));
            return;
        }

        let gameUI: any = UIManager.getInstance().getUI(Global.gameId);
        if (!gameUI) {
            Log.e('竟然获取不到界面' + Global.gameId);
            return;
        }

        if (Global.gameType == EGAME_TYPE.FISHING) {
            return;
        }

        this.close();
        UIManager.getInstance().closeToUI(UIID_GAME.UIBagView);
        let status = gameUI.getStatusWithUseXBK();
        if (status == 0) { // 判断条件满足，开始使用
            let times = Number(this.num.string);
            // GameCommonManager.getInstance().c2sActItemUse(this.itemVo.id, times, this.itemVo.gameIds[0]);
            if (!gameUI.isUsingXBK()) {
                if (times > 1) ComponentMgr.showTips("The use of Slotmania Cards begins!");
                GameComUtils.c2sStat(StatConst.CLICK_USE_ITEMS);
                gameUI.startUseXBK(this.itemVo.id, itemCfg.bet, times);
            } else {
                ComponentMgr.showTips(BagLangConfig.get("tryLater"));
            }
        } else {
            ComponentMgr.showTips(BagLangConfig.get("tryLater"));
        }
    }

    onJumpClicked() {
        let id = this.itemVo.gameIds[0];
        if (!id) return;

        GameComUtils.popupJumpDlg(id, this.close.bind(this));
    }

    private onCloseClicked() {
        this.close();
    }

}

