/**
 * @description 背包道具item
 * @author guohuo
 */
import { Component, EventTouch, ImageAsset, Label, NodeEventType, Sprite, SpriteFrame, Texture2D, _decorator, assetManager, resources } from "cc";
import { CCUtils } from "../../../../../scripts/common/utils/CCUtils";
import { UIManager } from "../../../../../scripts/framework/ui/UIManager";
import { BUNDLE_NAME, UIID_GAME } from "../../UIGameDefined";
import { ItemVo, BagModel, ActBagItemInfoVo_s2c, ItemType } from "./BagModel";
import { ResManager } from "../../../../../scripts/framework/manager/ResManager";
import { GameCommonManager } from "../../GameCommonManager";
import { Eventer } from "../../../../../scripts/framework/Eventer";
import { GameEventType } from "../../GameEventType";
import { GameComUtils } from "../../utils/GameComUtils";
import { StatConst } from "../../stat/StatConst";
import { GameCommonModel } from "../../GameCommonModel";
import GamesData from "../../GamesData";
const { ccclass, property } = _decorator;

@ccclass("BagItem")
export class BagItem extends Component {
    @property({ type: Sprite, visible: true })
    private icon: Sprite;
    @property({ type: Label, visible: true })
    private num: Label;
    @property({ type: Boolean, visible: true })
    private noClick = false;

    private _havePopup2 = false;
    set havePopup2(flag) {
        this._havePopup2 = flag
    }
    get havePopup2() {
        return this._havePopup2
    }
    private checkdata = [] // 二级弹窗数据

    private itemVo: ItemVo;
    static url2Sp: { [url: string]: SpriteFrame } = {};

    /**
     * 设置item数据
     * @param vo ItemVo
     * @param noClick 默认false，设置true，则不可点击
     */
    setData(vo: ItemVo, noClick: boolean = false) {
        this.itemVo = vo;
        this.noClick = noClick;
        let num = vo.num;
        if (vo.propType == ItemType.Score) num = GamesData.exact(num * GameCommonModel.getInstance().coinRate);
        this.setUI(vo.propIcon, num, noClick);
    }

    /**
     * 设置图标、数量、点击事件
     * @param icon 图标 url or path
     * @param num 道具数量
     * @param noClick 是否<不可点击>，默认可点击
     */
    setUI(icon: string, num: number = 1, noClick: boolean = false) {
        let defaultIcon = "resources/texture/bag/icon/default/spriteFrame"; //没有icon，默认icon
        icon = icon || defaultIcon;
        this.setIcon(icon);
        this.num.string = GameComUtils.numToKM(num);
        // this.num.node.active = num > 1;
        if (this.havePopup2) {
            this.node.on(NodeEventType.TOUCH_END, this.openPopup2, this);
        }
        if (!noClick) {
            this.node.on(NodeEventType.TOUCH_END, this.onClicked, this);
        }
    }

    /**
     * 简单好用的设置道具接口 (积分道具，虚拟道具特殊处理，仅传入类型ItemType.Score即可)
     * @param propId 道具配置id
     * @param propType 道具类型 积分道具用ItemType.Score
     * @param num 道具数量 平台传过来的值（积分需要换算）
     * @param noClick 是否<不可点击>，默认可点击
     * @param havePopup2 是否有二级弹窗，默认否
     * @param checkdata 二级弹窗所需数据
     */
    setEasyData(propId: number, propType: number, num: number = 1, noClick: boolean = false, havePopup2: boolean = false, checkdata = []) {
        this.havePopup2 = havePopup2;
        this.checkdata = checkdata
        num = num || 1;
        if (propType == ItemType.Score) {
            this.itemVo = new ItemVo("", 0, ItemType.Score, "", num);
            this.noClick = noClick;
            num = GamesData.exact(num * GameCommonModel.getInstance().coinRate);
            this.setUI("resources/texture/bag/icon/icon2/spriteFrame", num, noClick);
            return;
        }

        let cfg = BagModel.getInstance().getItemCfg(propId, propType);
        if (!cfg) {
            this.itemVo = new ItemVo("", propId, propType, "", num);
            this.noClick = noClick;
            this.setUI("", num, true);
            GameCommonManager.getInstance().c2sActItemInfo(propId, propType);
            Eventer.getInstance().on(GameEventType.act_item_info, this.onUpdateItem, this);
            return;
        }

        let itemVo = new ItemVo("", propId, cfg.propType, cfg.propIcon, num);
        this.setData(itemVo, noClick);
    }


    /**
     * 设置图标
     * @param urlOrPath url或者本地资源
     */
    setIcon(urlOrPath: string, bundleName = BUNDLE_NAME.gamesCommon) {
        if (urlOrPath.search("http") != -1) {
            if (!BagItem.url2Sp[urlOrPath]) {
                CCUtils.setSpriteFrame(this.icon, urlOrPath, (err: any, sp: SpriteFrame) => {
                    BagItem.url2Sp[urlOrPath] = sp;
                });
            } else this.icon.spriteFrame = BagItem.url2Sp[urlOrPath];
        } else {
            ResManager.Instance().load(bundleName, urlOrPath, SpriteFrame, null, (cacheData) => {
                this.icon.spriteFrame = cacheData.data as SpriteFrame;
            });
        }
    }

    /**
     * 设置数目是否可见
     * @param vis 
     */
    setNumVisible(vis: boolean) {
        this.num.node.active = vis;
    }

    onClicked(e?: EventTouch) {
        if (this.havePopup2) {
            return
        }
        // return
        GameComUtils.c2sStat(StatConst.CLICK_VIEW_ITEMS);
        UIManager.getInstance().open(UIID_GAME.UIItemDetailDlg, this.itemVo);
        e.propagationStopped = true;
    }
    //打开二级弹窗
    openPopup2() {
        Log.d("popup2")
        GameComUtils.c2sStat(StatConst.CLICK_VIEW_ITEMS);
        UIManager.getInstance().open(UIID_GAME.SecondaryPopup, this.checkdata);
    }

    onUpdateItem(msg: ActBagItemInfoVo_s2c) {
        if (!this.node || !this.itemVo) {
            Eventer.getInstance().offName(GameEventType.act_item_info, this);
            return;
        }
        let cfg = BagModel.getInstance().getItemCfg(this.itemVo.propId, this.itemVo.propType);
        if (!cfg) return;

        Eventer.getInstance().offName(GameEventType.act_item_info, this);
        this.itemVo.propIcon = cfg.propIcon;
        this.setIcon(cfg.propIcon);
        if (this.havePopup2) {
            this.node.on(NodeEventType.TOUCH_END, this.openPopup2, this);
        }
        if (!this.noClick) this.node.on(NodeEventType.TOUCH_END, this.onClicked, this);
    }

    protected onDestroy(): void {
        Eventer.getInstance().offName(GameEventType.act_item_info, this);
    }
}

