    /** 加载开始时间 */
    public startLoadingTime: number;
    /** 进游戏总加载时间 */
    public get totalLoadingTime(): number {
        let nowTime = Date.now();
        let loadTime = nowTime - this.startLoadingTime;
        let gameHideTime = GameManager.getInstance().gameHideTime;
        if (gameHideTime > 0) {
            if (gameHideTime > this.startLoadingTime && gameHideTime < nowTime) {
                loadTime -= GameManager.getInstance().gameHideTotalTime;
                if (loadTime < 0)
                    loadTime = 0;
            }
        }
        return loadTime;
    }
