import { _decorator, Component, NodeEventType, Label, SpriteFrame, Sprite, Node, Color } from "cc";
import { ResManager } from "../../../../../scripts/framework/manager/ResManager";
import { ScreenType, UIView } from "../../../../../scripts/framework/ui/UIView";
import { Global } from "../../../../../scripts/main/Global";
import { BUNDLE_NAME } from "../../UIGameDefined";
import { UIButton } from "../../../../../scripts/framework/ui/basic_ui/UIButton";
const { ccclass, property } = _decorator;

@ccclass('ComAcitivityTab')
export class ComAcitivityTab extends Component {
    private _clickCallBack: Function = null;
    private _uiList: { [key: string]: Node } = {};
    private _tabIndex: number = -1;

    private tabList: Array<string>;
    private titleName: string;
    private curScreenType: string;
    /**是否是子标签*/
    private issub = false
    readonly TabNum: number = 5;

    public clickCloseHandler: Function;
    onLoad(): void {
        this.initUI();
    }

    start() {

    }

    onDestroy() {
    }

    private SerializableUIControlNode(root: Node) {
        if (!root) {
            return;
        }

        let children = root.children;
        for (let k in children) {
            let child = children[k];
            let name = child.name;
            this._uiList[name] = child;
            if (child.children.length >= 1) {
                this.SerializableUIControlNode(child);
            }
        }
    }

    private initUI() {
        this._uiList = {};
        this._uiList[ScreenType.Landscape] = this.node.getChildByName(ScreenType.Landscape);
        this._uiList[ScreenType.Portrait] = this.node.getChildByName(ScreenType.Portrait);
    }

    private bindEvent() {
        for (let i = 1; i <= this.TabNum; i++) {
            this._uiList["tab_" + i].on(NodeEventType.TOUCH_END, () => {
                this.selectTab(i);
            }, this);
        }

        this._uiList["btnClose"].getComponent(UIButton).touchEndedFun = this.clickBtnClose.bind(this);
    }

    private clickBtnClose() {
        if (!this.clickCloseHandler) {
            let rootNode = this.node.parent;
            while (rootNode) {
                if (rootNode.getComponent(UIView)) break;
                rootNode = rootNode.parent;
            }
            if (rootNode) rootNode.getComponent(UIView).close();
        } else {
            this.clickCloseHandler();
        }
    }

    public get tabIndex(): number {
        return this._tabIndex;
    }

    public initData(tabList: Array<string>, titleName?: string, ClickCallBack: Function = null, issub = false) {
        let screenType = Global.gameScreenType;
        let isLandscape = screenType == ScreenType.Landscape;
        this._uiList[ScreenType.Landscape].active = isLandscape;
        this._uiList[ScreenType.Portrait].active = !isLandscape;
        this.issub = issub;
        this.SerializableUIControlNode(this.node.getChildByName(screenType));
        this.bindEvent();

        for (let i = 1; i <= this.TabNum; i++) {
            let tab: Node = this._uiList["tab_" + i];
            tab.active = false;
        }

        for (let i = 0; i < tabList.length; i++) {
            let tab: Node = this._uiList["tab_" + (i + 1)];
            tab.active = true;
            let labTabName = tab.getChildByName("labTabName").getComponent(Label);
            labTabName.string = tabList[i];
            let imgTabBag = tab.getChildByName("imgTabBg");
            imgTabBag.active = false;
        }

        this.setTitleName(titleName);

        this.tabList = tabList;
        this._clickCallBack = ClickCallBack;
        this.curScreenType = screenType;
    }

    public selectTab(index: number) {
        let preTab;
        if (this._tabIndex > 0) {
            let tab = this._uiList["tab_" + this._tabIndex];
            tab.getChildByName("imgTabBg").active = false;
            preTab = tab;
        }

        this._tabIndex = index;

        let curTab = this._uiList["tab_" + this._tabIndex];
        curTab.getChildByName("imgTabBg").active = true;

        if (this._clickCallBack) {
            this._clickCallBack(index - 1, preTab, curTab);
        }
    }

    public init(...args: any[]): void {
        let screenType = Global.gameScreenType;
        let isLandscape = screenType == ScreenType.Landscape;
        this._uiList[ScreenType.Landscape].active = isLandscape;
        this._uiList[ScreenType.Portrait].active = !isLandscape;

        this.SerializableUIControlNode(this.node.getChildByName(screenType));
        this.bindEvent();
    }

    public addChildView(viewNode: Node) {
        this.node.addChild(viewNode);
    }

    public setTitleName(name: string) {
        if (name) {
            this._uiList["labTitle"].getComponent(Label).string = name;
            this.titleName = name;
        }
    }

    public screenSwitch() {
        if (this.curScreenType == Global.gameScreenType) return;
        if (!this.tabList) return;
        this.initData(this.tabList, this.titleName, this._clickCallBack, this.issub);
    }

    // public initOk(names: string[], title?: string, cb?: Function, selIndex?: number) {
    //     this.initData(names, title, cb);
    //     if (selIndex) this.selectTab(selIndex);
    // }
}