/**道具基本数据 c */
export interface ItemBaseVo {
    propId: number;
    propType: number;
    num: number;
}

/**道具配置数据 c*/
export class ItemConfig {
    propId: number;     // 道具配置id
    propType: number;   // 注：propId和propType才能确定唯一道具配置id
    propName: string;
    propIcon: string;
    propDesc: string;
    bet: number; // 指定押注
    isShowBet: number; // 0,1
    balanceLimit: number; // 余额限制
    currency: string; // 币种，eg：CNY，USD
    gameIds: number[]; // 游戏Ids，用于那些游戏上

    isHasDetailData?: boolean = false; // 是否有详细道具数据 对应字段desc以下的是否具有
}

/**道具数据 c*/
export class ItemVo {
    id: string; // 道具唯一id 使用后台给的code，真的捞，搞tm个唯一id就搞不明白
    propId: number; // 道具配置id   注：propId和propType才能确定唯一道具配置id
    propType: number; // 道具类型
    propIcon: string; // 道具图标
    num: number; // 道具数量
    gameIds: number[]; // 游戏Ids，用于那些游戏上
    useTimeBegin?: number; // 可用时间起
    useTimeEnd?: number; // 可用时间止

    isInBag: boolean = false; // 是否在背包中 默认不在

    constructor(id?: string, propId?: number, propType?: number, propIcon?: string,
        num?: number, isInBag: boolean = false) {
        this.id = id;
        this.propId = propId;
        this.propType = propType;
        this.propIcon = propIcon;
        this.num = num;
        this.isInBag = isInBag;
    }
}

/**道具类型定义 */
export enum ItemType {
    Score = -1, // 积分卡 (虚拟道具，不存在背包中）
    Xbk = 0, // 虚宝卡
}

// 背包道具数据 s
export interface ActBagItemVo {
    id: string;
    code: string;
    gamePropId: number;
    propId: number;
    propIcon: string;
    propName: string;
    propType: number;
    num: number;
    gameIds: number[];
    useTimeBegin: number;
    useTimeEnd: number;
    uid?: number;
}
export interface ActBagVo_s2c {
    records: Array<ActBagItemVo>;
    size: number; //每页数量
    total: number; //总条数
    pages: number; //总页数
    current: number; //当前页
    gameId: number;
}

// 道具详情数据 s
export interface ActBagItemInfoVo_s2c {
    gamePropId: number;
    propId: number;
    propType: number;
    propName: string;
    propIcon: string;
    propDesc: string;
    bet: number; // 指定押注
    isShowBet: number; // 0,1
    balanceLimit: number; // 余额限制
    currency: string; // 币种，eg：CNY，USD
    gameIds: number[]; // 游戏Ids，用于那些游戏上
}

// 道具使用数据 s
export interface ActBagItemUseVo_s2c {
    id: number;
    num: number;
    using: number;
}

// 背包讯息数据 s
export interface ActBagInfoVo {
    /**
     * 1: 物品获得-任务	2: 物品获得-排行榜	3: 物品使用-虚宝卡
     */
    type: number;
    //获得的道具列表
    props: Array<{ num: number, propName: string }>;
    // 任务名称》type=1 时有此字段 名次》 type=2时有此字段 总收益 》type=3时有此字段
    info: { taskName: string, ranking: string, currency: string, totalBenefit: number, vipLevel, };
    // 时间戳
    time: number;
    // 唯一键值
    id: number;

}
export interface ActBagInfo_s2c {
    records: Array<ActBagInfoVo>;
    size: number;
    total: number;
    pages: number;
    current: number;
}


export class BagModel extends Singleton<BagModel>() {
    private propTId2Cfg: { [propTId: number]: ItemConfig } = {};
    public id2ItemVo: { [id: string]: ItemVo } = {};
    public itemVos: ItemVo[] = []; // 背包中所有的物品 与id2ItemVo公用ItemVo数据
    public totalNum: number; // 所有物品数量
    public curReqPage: number = 0; // 当前请求的页码
    public curTotPage: number = 0; // 当前需请求的总页码
    static readonly size: number = 20; // 每页数量

    updateBagList(data: ActBagVo_s2c) {
        if (data.total == 0) {
            this.totalNum = 0;
            this.itemVos.length = 0;
            this.id2ItemVo = {};
            this.curReqPage = this.curTotPage = 0;
            return;
        }

        // 暂时简易处理
        this.totalNum = data.total;
        this.curTotPage = data.pages;
        if (data.current == 1) { // 从第一页开始物品列表置空，然后一页一页的请求完数据
            this.itemVos.length = 0;
            this.curReqPage = 0;
        }

        if (data.current != this.curReqPage + 1) {
            Log.d("current page error! should page = " + (this.curReqPage + 1), data);
            data.current = this.curReqPage;
            Log.d("repair current page for next req, current = " + this.curReqPage);
            return;
        }

        this.curReqPage = data.current;
        for (let i = 0; i < data.records.length; ++i) {
            let abiv = data.records[i];
            if (this.itemVos.length >= data.total) {
                Log.e("itemVos full!!!", data);
                break;
            }

            let itemVo = this.createItemVo(abiv);
            this.itemVos.push(itemVo);
        }
    }

    updateItemConfig(data: ActBagItemInfoVo_s2c) {
        let itemCfg = this.getItemCfg(data.propId, data.propType);

        if (!itemCfg) {
            itemCfg = new ItemConfig();
            itemCfg.propId = data.propId;
            itemCfg.propType = data.propType;
            itemCfg.propName = data.propName;
            itemCfg.propIcon = data.propIcon;
        }

        itemCfg.propDesc = data.propDesc;
        itemCfg.bet = data.bet; // 后台配置押注列表时钱*1000的，后台传回这里的值时已*1000，无需处理了
        itemCfg.isShowBet = Number(data.isShowBet);
        itemCfg.balanceLimit = data.balanceLimit * GamesData.exchange; // 后台数据需乘以exchange
        itemCfg.currency = data.currency;
        itemCfg.gameIds = data.gameIds;
        itemCfg.isHasDetailData = true;

        this.setItemCfg(data.propId, data.propType, itemCfg);
    }

    updateBagAfterItemUse(data: ActBagItemUseVo_s2c) {
        // let itemVo = this.id2ItemVo[data.id];
        // if(!itemVo) return ;

        // for(let i = 0; i < this.itemVos.length; ++i) {
        //     let vo = this.itemVos[i];
        //     if(vo.id == data.id) {
        //         if(vo.num <= data.num) {
        //             this.itemVos.splice(i, 1);
        //             this.id2ItemVo[data.id] = undefined;
        //         } else {
        //             vo.num -= data.num;
        //         }
        //         break;
        //     }
        // }

    }

    createItemVo(from: ActBagItemVo) {
        let itemVo = this.id2ItemVo[from.code];
        if (!itemVo) {
            itemVo = new ItemVo();
        }
        itemVo.id = from.code
        itemVo.propId = from.propId;
        itemVo.propType = from.propType;
        itemVo.propIcon = from.propIcon;
        itemVo.num = from.num;
        itemVo.useTimeBegin = from.useTimeBegin;
        itemVo.useTimeEnd = from.useTimeEnd;
        itemVo.gameIds = [];
        itemVo.isInBag = true;
        for (let id of from.gameIds) {
            itemVo.gameIds.push(Number(id));
        }
        // itemVo.gameIds= from.gameIds;
        this.id2ItemVo[itemVo.id] = itemVo;

        let itemCfg = this.getItemCfg(from.propId, from.propType);
        if (!itemCfg) {
            itemCfg = new ItemConfig();
            itemCfg.propId = from.propId;
            itemCfg.propType = from.propType
            itemCfg.propName = from.propName;
            itemCfg.propIcon = from.propIcon;
            this.setItemCfg(from.propId, from.propType, itemCfg);
        }

        return itemVo;
    }

    // 0: this game 1: other game
    getItemVosByIndex(index: number) {
        let itemVos: ItemVo[] = [];
        let gameId = Global.gameId;

        let serverTime = Global.svrTimeMS;
        if (index == 0) {
            for (let i = 0; i < this.itemVos.length; ++i) {
                let vo = this.itemVos[i];
                if (vo.gameIds.indexOf(gameId) != -1 /*&& vo.useTimeEnd > serverTime*/) {
                    itemVos.push(vo);
                }
            }
        } else if (index == 1) {
            for (let i = 0; i < this.itemVos.length; ++i) {
                let vo = this.itemVos[i];
                if (vo.gameIds.indexOf(gameId) == -1 /*&& vo.useTimeEnd > serverTime*/) {
                    itemVos.push(vo);
                }
            }
        }

        return itemVos;
    }

    getItemCfg(propId: number, propType = 0): ItemConfig {
        let key = propId + "_" + propType;
        return this.propTId2Cfg[key];
    }

    setItemCfg(propId: number, propType: number, itemCfg: ItemConfig) {
        let key = propId + "_" + propType;
        this.propTId2Cfg[key] = itemCfg;
    }
}