    private _itemTab3List: any = [];

    start() {
        this.node.zIndex = UIZIndex.actUI;
    }

    protected onDestroy(): void {
        Eventer.getInstance().offName(GameEventType.act_task_setting, this);
        Eventer.getInstance().offName(GameEventType.act_tasks, this);
        Eventer.getInstance().offName(GameEventType.get_task_awards, this);
        Eventer.getInstance().offName(GameTaskEvent.open_task_pop_view, this);
        Eventer.getInstance().offName(GameTaskEvent.open_task_select_pop_view, this);
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
    }

    private SerializableUIControlNode(root: Node) {
        if (!root) {
            return;
        }
        let children = root.children;
        for (let k in children) {
            let child = children[k];
            let name = child.name;
            this._uiList[name] = child;
            if (child.children.length >= 1) {
                this.SerializableUIControlNode(child);
            }
        }
    }

    public bindEvent() {
        this._uiList["btn_help"].on(NodeEventType.TOUCH_END, () => {
            GameComUtils.c2sStat(StatConst.CLICK_TASK_EXPLAIN);
            UIManager.getInstance().open(UIID_GAME.UIComHelpDlg, this.taskHelpStr);
        }, this);

    }

    public selectTab(index: number) {
        this._tabIndex = index;

        if (index == 1) {
            let sdata: any = {};
            sdata.status = 1;
            GameComUtils.c2sStat(StatConst.OPEN_DAILY_TASK);
            GameTaskModel.getInstance().c2sSlotTaskInfo(sdata);
        } else if (index == 2) {
            let sdata: any = {};
            sdata.status = 5;
            GameComUtils.c2sStat(StatConst.OPEN_TASK_PREDICTION);
            GameTaskModel.getInstance().c2sSlotTaskInfo(sdata);
        }
    }
    /**
     * 初始化语言
     * @param node 需要初始化的节点
     * @param code 语言种类编号
     */
    private initLanguage(node, code) {
        if (node.getComponent(Label)) {
            node.getComponent(Label).string = i18n.tr(code)
            // Log.w("string,", node.getComponent(Label).string, '-', Global.language)
        }

    }

    private initUIList(): void {
        let node: Node;
        if (Global.gameScreenType == ScreenType.Portrait) {
            let Node_shu: Node = this.node.getChildByName("Node_shu");
            let Node_heng: Node = this.node.getChildByName("Node_heng");

            Node_shu.active = true;
            Node_heng.active = false;
            node = Node_shu;
        }
        else {
            let Node_heng: Node = this.node.getChildByName("Node_heng");
            let Node_shu: Node = this.node.getChildByName("Node_shu");

            Node_shu.active = false;
            Node_heng.active = true;
            node = Node_heng;
        }

        this.SerializableUIControlNode(node);
        this.bindEvent();
    }

    public onOpen(): void {
        this.addEvents();

        this.onScreenSwitch();
    }

    private addEvents() {
        GameTaskModel.getInstance().registerMsgMap();

        Eventer.getInstance().offName(GameEventType.act_task_setting, this);
        Eventer.getInstance().offName(GameEventType.act_tasks, this);
        Eventer.getInstance().offName(GameEventType.get_task_awards, this);
        Eventer.getInstance().offName(GameTaskEvent.open_task_pop_view, this);
        Eventer.getInstance().offName(GameTaskEvent.open_task_select_pop_view, this);
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
        Eventer.getInstance().on(GameEventType.act_task_setting, this.on_act_task_setting, this);
        Eventer.getInstance().on(GameEventType.act_tasks, this.on_act_tasks, this);
        Eventer.getInstance().on(GameEventType.get_task_awards, this.on_get_task_awards, this);
        Eventer.getInstance().on(GameTaskEvent.open_task_pop_view, this.on_open_task_pop_view, this)
        Eventer.getInstance().on(GameTaskEvent.open_task_select_pop_view, this.on_open_task_select_pop_view, this)
        Eventer.getInstance().on(GameEventType.ScreenSwitch, this.onScreenSwitch, this);
    }

    public onScreenSwitch() {
        this.initUIList();
        this.actTab.initData([i18n.tr(2001002), i18n.tr(2001015)], "QUESTS", (i) => this.selectTab(i + 1));
        this.actTab.selectTab(this._tabIndex ? this._tabIndex : 1);
        this.actTab.screenSwitch();

        this.c2sTskTypeInfo();
    }

    public c2sTskTypeInfo() {
        GameTaskModel.getInstance().c2sSlotTaskSetting();
    }

    private taskHelpStr: string = "";
    public on_act_task_setting(data: any) {
        let dailyReminder = this.getLanguageValue(data?.dailyReminder);
        if (!dailyReminder || dailyReminder == "") {
            dailyReminder = data?.dailyReminder?.defaultValue;
        }
        let Label_daily_tips: Node = this._uiList["Label_daily_tips"];
        Label_daily_tips.getComponent(Label).string = dailyReminder;

        let descTitle = this.getLanguageValue(data?.descTitle);
        if (!descTitle || descTitle == "") {
            descTitle = data?.descTitle?.defaultValue;
        }

        let descContent = this.getLanguageValue(data?.descContent);
        if (!descContent || descContent == "") {
            descContent = data?.descContent?.defaultValue;
        }

        this.taskHelpStr = descContent;
    }

