    /** 投注比例 */
    private _coinRate: number = 1;
    public get coinRate(): number {
        if (Global.playback) return Global.playbackCoinRate;
        return this._coinRate;
    }
    public set coinRate(rate: number) {
        this._coinRate = rate;
        if (isNaN(rate) || rate <= 0) {
            Log.w(`coin rate has error,coinrate is ${rate}, default to 1`);
            this._coinRate = 1;
        }
        if (this._coinRate < 10) {
            this._scorePoint = 2;
        }
        else if (this._coinRate < 100) {
            this._scorePoint = 1;
        }
        else {
            this._scorePoint = 0;
        }

        if (GamesData.ctlArea) {
            /** 受平台控制 */
            if (!GamesData.point) {
                this._scorePoint = 0;
            }
        } else {
            /** 不受平台控制 */
            // GamesData.isSeparation = false;
        }
    }
    /** 押注列表 */
    private _betList: number[] = [1,1,1,1,1];
    public get betList(): number[] {
        return this._betList;
    }
    public set betList(mList: number[]) {
        if (!mList || mList.length < 1) {
            Log.e("押注列表不能为空！！");
        }
        this._betList = mList;
    }
    //最小押注
    private _minBet: number;
