    /** 消耗 */
    public slotCost: number;

    //默认押注的索引
    // private _defaultBetIndex: number = 0;
    public get defaultBetIndex(): number {
        return this.betList.indexOf(this.defaultBet);
    }

    /** 必须先设置 betList 和 defaultBet 才能执行更新 */
    public updateBetList(max: number, min: number) {
        if (isNaN(max) || isNaN(min)) {
            Log.e("押注列表的最大最小值不能空！！！");
            return;
        }

        if (!this.betList || this.betList.length < 1) {
            Log.e("押注列表不能为空！！");
            return;
        }

        if (max < min) {
            let temp: number = min;
            max = min;
            min = temp;
            Log.w("押注列表大小值设置有误！");
        }
        /** 截取押注列表有效范围 */
        for (let i: number = this.betList.length - 1; i >= 0; --i) {
            let bet: number = this.betList[i];
            if (bet < min || bet > max) {
                this.betList.splice(i, 1);
            } else if (this.betList.indexOf(bet) != i) {
                /** 去重 */
                this.betList.splice(i, 1);
            }
        }
        this.betList.sort((a, b) => a - b);

        if (!this.betList || this.betList.length < 1) {
            Log.e("押注列表过滤后空了！！");
            return;
        }
        this._minBet = this.betList[0];
        this._maxBet = this.betList[this.betList.length - 1];
        /** 纠正默认押注 */
        if (this.betList.indexOf(this.defaultBet) < 0) {
            this.defaultBet = this.betList[0];
        }
    }

