    /**设置当前押注值 */
    public setCurBet(bet: number) {
        if (!this._betList) return false;

        for (let i = 0; i < this._betList.length; ++i) {
            if (this._betList[i] == bet) {
                this._curBetIndex = i;
                console.log("setCurBet==========", this._curBetIndex);
                return true;
            }
        }

        Log.e("set curBet: cannot find bet from betList", bet, this._betList);
        return false;
    }

