    //--------------虚宝卡使用相关----------------
    // 记录下注数目及滚轮次数，是否为空可作为是否正在使用虚宝卡的状态
    public usingXBKObj: { id: string, bet: number, times: number, totTimes: number };
    /**
     * 判断是否正在使用虚宝卡
     * 通用方法，无需修改
     */
    isUsingXBK(): boolean {
        if (!this.usingXBKObj) return false;
        return this.usingXBKObj.times > 0;
    }

    /**
     * 设置虚宝卡使用数据
     * @param id 虚宝卡id
     * @param bet 下注数目
     * @param times 滚轮次数
     */
    setUsingXBKObj(id: string, bet: number, times: number) {
        if (!this.usingXBKObj) this.usingXBKObj = { id: "", bet: 0, times: 0, totTimes: 0 };
        this.usingXBKObj.id = id;
        this.usingXBKObj.bet = bet;
        this.usingXBKObj.times = times || 1;
        this.usingXBKObj.totTimes = this.usingXBKObj.times;
    }

    /**
     * 使用一张虚宝卡
     */
    c2sUseOneXBK() {
        // 发送使用虚宝卡协议 一次用一张
        GameCommonManager.getInstance().c2sActItemUse(this.usingXBKObj.id, 1, Global.gameId);
        this.usingXBKObj.times--;
        if (this.usingXBKObj.totTimes > 1 && this.usingXBKObj.times == 0) {
            ComponentMgr.showTips("Last use of Slotmania Cards");
        }
    }
