import { _decorator, Asset, AssetManager, assetManager } from 'cc';
import { DEBUG } from 'cc/env';
import { Resource } from '../../../scripts/framework/hall/Resource';
import { CacheManager } from '../../../scripts/framework/manager/CacheManager';
import { ReleaseManager } from '../../../scripts/framework/manager/ReleaseManager';
import { ResManager } from '../../../scripts/framework/manager/ResManager';
import { GameCommonManager } from './GameCommonManager';
const { ccclass, property } = _decorator;

@ccclass('GameResourceLoader')
/** 游戏loader */
export class GameResourceLoader {

    /** 每次加载文件数量 */
    private readonly _LOADER_NUM: number = 10;

    private _timerId: number = 0;
    /** 当前加载的游戏id */
    private _loadingId: number = 0;
    /** 在加载的资源的index */
    private _loaderIxd: number = 0;

    /**  加载资源数据 */
    protected _resources: Map<string, Resource.Data>= new Map<string, Resource.Data>();
    /** 当前已经加载的资源数量 */
    protected _loadedCount: number = 0;

    /** 加载完成后的数据，为了方便释放时精准释放，没加载成功的资源，不在做释放的判断 */
    protected _loadedResource: Map<string, Resource.Info> = new Map<string, Resource.Info>();

    /** 当前是否正在加载资源 */
    protected _isLoading: boolean = false;

    /** 标识 */
    private _tag: string = null!;
    public get tag() {
        return this._tag;
    }
    public set tag(tag: string) {
        this._tag = tag;
    }

    /** 加载完成回调 */
    private _onLoadComplete?: (error: Resource.LoaderError) => void;
    public set onLoadComplete(cb) {
        this._onLoadComplete = cb;
    }
    public get onLoadComplete() {
        return this._onLoadComplete;
    }

    /** 加载进度 */
    private _onLoadProgress?: (loadedCount: number, total: number, data: Resource.CacheData, itemData?: AssetManager.RequestItem) => void;
    public set onLoadProgress(value) {
        this._onLoadProgress = value;
    }
    public get onLoadProgress() {
        return this._onLoadProgress;
    }

    /**
     *  实现类必须给个需要加载资源
     */
    private _getLoadResource?: () => Resource.Data[];
    public set getLoadResources(func) {
        this._getLoadResource = func;
    }
    public get getLoadResources() {
        return this._getLoadResource;
    }

    /**
    *  加载游戏资源
    */
    public loadGameResources(gameId: number) {
        if (!this.getLoadResources) {
            if (DEBUG) Log.e("未指定 getLoadResources 函数");
            this.onLoadComplete && this.onLoadComplete(Resource.LoaderError.NO_FOUND_LOAD_RESOURCE);
            return;
        }

        let res = this.getLoadResources();
        if (!res) {
            if (DEBUG) Log.e(`未指定加载资源`);
            this.onLoadComplete && this.onLoadComplete(Resource.LoaderError.NO_FOUND_LOAD_RESOURCE);
            return;
        }
        if (res.length <= 0) {
            if (DEBUG) Log.w(`加载的资源为空`);
            this.onLoadComplete && this.onLoadComplete(Resource.LoaderError.NO_FOUND_LOAD_RESOURCE);
            return;
        }

        //如果正在加载中，防止重复调用
        if (this._isLoading) {
            if (DEBUG) Log.w(`资源加载中，未完成加载`);
            this.onLoadComplete && this.onLoadComplete(Resource.LoaderError.LOADING);
            return;
        }

        if (this._resources.size > 0 && this.isLoadComplete()) {
            if (DEBUG) Log.w(`资源已经加载完成，使用已经加载完成的资源`);
            this.onLoadComplete && this.onLoadComplete(Resource.LoaderError.SUCCESS);
            this.onLoadResourceComplete();
            return;
        }

        this._isLoading = true;
        this._loadingId = gameId;
        //为防止重复，这里把资源放在一个map中
        res.forEach((value, index) => {
            if (value.url) {
                this._resources.set(value.url, value);
            } else if (value.dir) {
                this._resources.set(value.dir, value);
            }
        });

        this._loadedCount = 0;
        this._loaderIxd = 0;
        this.loadGameRes();
        this._timerId = setInterval(this.onTime.bind(this), 1);
    }

    private onTime(): void {
        // Log.d("resources onTime ... ");
        if (this._isLoading == false) {
            clearInterval(this._timerId);
            return;
        }
        if (this._loaderIxd < this._resources.size) {
            if (this._resources.size - this._loaderIxd > this._LOADER_NUM && this._loaderIxd - this._loadedCount > this._LOADER_NUM) {
                return;
            }
            this.loadGameRes();
        }
        else {
            clearInterval(this._timerId);
        }
    }
    private loadGameRes(): void {
        let res = this.getLoadResources();
        let value;
        value = res[this._loaderIxd];
        this._loaderIxd++;
        if (!value) {
            return;
        }

        let cache = CacheManager.getInstance().get(value.bundle, value.url);
        if (cache) {
            this._onLoadResourceComplete(cache);
            return;
        }
        // Log.e("idx == " + (this._loaderIxd - 1) + ": " + value.url);
        ResManager.Instance().load(
            value.bundle as BUNDLE_TYPE,
            value.url as string,
            <any>value.type,
            <any>null,
            (data: Resource.CacheData) => { this._onLoadResourceComplete(data); }
        );
    }

    protected _onLoadResourceComplete(data: Resource.CacheData) {
        if (data.info.bundle != this._loadingId + "") {
            this._loadedCount++;
            if (data.info.type) {
                assetManager.releaseAsset(data.data as Asset);
            }
            else {
                Log.e(data.info.url + "不是 Asset");
            }

            if (this._isLoading) {
                this.checkLoadResourceComplete();
            }
            else if (this._loadedCount >= this._loaderIxd) {
                this.unLoadResources();
                GameCommonManager.getInstance().backToHall();
                GameCommonManager.getInstance().releaseRec();
            }
            return;
        }

        this._loadedCount++;
        // Log.d("this._loadedCount === " + this._loadedCount);
        if (this.onLoadProgress) {
            if (this._loadedCount > this._resources.size) {
                this._loadedCount = this._resources.size;
            }
            this.onLoadProgress(this._loadedCount, this._resources.size, data);
        }

        if (data && (Array.isArray(data.data) || data.data instanceof Asset)) {
            //排除掉界面管理器
            let info = new Resource.Info();
            info.url = data.info.url;
            info.type = data.info.type;
            info.data = data.data;
            info.bundle = data.info.bundle;
            ResManager.Instance().retainAsset(info);
            this._loadedResource.set(info.url, info);
        }

        this.checkLoadResourceComplete();
    }

    /**
    *  资源加载完成
    */
    protected checkLoadResourceComplete() {
        if (!this._isLoading) {
            return;
        }
        //抛出事件给业务逻辑处理
        if (this.isLoadComplete()) {
            //加载完成
            this._isLoading = false;
            this.onLoadComplete && this.onLoadComplete(Resource.LoaderError.SUCCESS);
            this.onLoadResourceComplete();
        }
    }

    /**
     * stopLoading 断掉加载
     */
    public stopLoading() {
        this._isLoading = false;
        this._loadingId = 0;
        if (this._loadedCount >= this._loaderIxd) {
            this.unLoadResources();
            GameCommonManager.getInstance().backToHall();
            GameCommonManager.getInstance().releaseRec();
        }
    }

    /**
     *  卸载已经加载资源资源
     */
    public unLoadResources() {
        this._unLoadResources();
    }

    private _unLoadResources() {
        clearInterval(this._timerId);
        if (this._isLoading || this._resources.size <= 0) {
            //当前正在加载中
            if (this._isLoading) {
                Log.d("resources is loading , waiting for unload!!!");
            }
            return;
        }

        this._resources.forEach((value) => {
            if (value.url) {
                if (this._loadedResource.has(value.url)) {
                    let data = this._loadedResource.get(value.url);
                    if (data) {
                        this.removeWithInfo(data);
                        ReleaseManager.Instance().release(data);
                    }
                    this._loadedResource.delete(value.url);
                }
            } else if (value.dir) {
                if (this._loadedResource.has(value.dir)) {
                    let data = this._loadedResource.get(value.dir);
                    if (data) {
                        this.removeWithInfo(data);
                        ReleaseManager.Instance().release(data);
                    }
                    this._loadedResource.delete(value.dir);
                }
            }
        });

        //重置标记
        this._isLoading = false;
        this._loadedCount = 0;
        this._resources.clear();
        this._resources=null;
        this._resources= new Map<string, Resource.Data>();
    }

    private removeWithInfo(info: Resource.Info) {
        if (!info) {
            Log.w(`info is null`);
            return;
        }
        if (!info.data) {
            Log.w(`info.data is null , bundle : ${info.bundle} url : ${info.url}`);
            return;
        }
        if (Array.isArray(info.data)) {
            for (let i = 0; i < info.data.length; i++) {
                while (info.data[i].refCount > 0) {
                    info.data[i].decRef(false);
                }
                CacheManager.getInstance().remove(info.bundle, info.url);
            }
        } else {
            while (info.data.refCount > 0) {
                info.data.decRef(false);
            }
            CacheManager.getInstance().remove(info.bundle, info.url);
        }
    }

    /** 加载资源完成 */
    protected onLoadResourceComplete() { }

    public isLoadComplete(): boolean {
        return this._loadedCount >= this._resources.size;
    }

}

