/**
 * @description 奖励列表小弹窗
 * @author guohuo
 */

import { _decorator, instantiate, Label, Node, Prefab, Sprite, UITransform, Vec3, warn } from 'cc';
import { ScreenType, UIView, UIZIndex } from '../../../../../scripts/framework/ui/UIView';
import { Eventer } from '../../../../../scripts/framework/Eventer';
import { GameEventType } from '../../GameEventType';
import { Global } from '../../../../../scripts/main/Global';
import { GameComUtils } from '../../utils/GameComUtils';
import { UIButton } from '../../../../../scripts/framework/ui/basic_ui/UIButton';
import { ResManager } from '../../../../../scripts/framework/manager/ResManager';
import { BagItem } from './BagItem';
import { ItemType } from './BagModel';
import i18n from '../../../../../scripts/framework/language/i18n';
const { ccclass, property } = _decorator;


@ccclass('SecondaryPopup')
export class SecondaryPopup extends UIView {
    private uiList: { [key: string]: Node } = {};

    init(...args): void {
        this.node.zIndex = UIZIndex.actUI;
    }

    onLoad(): void {
        this.initUI();
        this.bindEvent();
    }

    start() {
        Eventer.getInstance().on(GameEventType.ScreenSwitch, this.onScreenSwitch, this);
    }

    private SerializableUIControlNode(root: Node) {
        if (!root) {
            return;
        }
        let children = root.children;
        for (let k in children) {
            let child = children[k];
            let name = child.name;
            this.uiList[name] = child;
            if (child.children.length >= 1) {
                this.SerializableUIControlNode(child);
            }
        }
    }

    public initUI() {
        this.SerializableUIControlNode(this.node);
        this.uiList["item"].active = false;
    }

    public bindEvent() {
        let closeBtn = this.uiList["btnClose"];
        // Log.d("btnClose,", closeBtn, this.uiList)
        closeBtn.getComponent(UIButton).touchEndedFun = this.close.bind(this);
    }

    public onOpen(chect_data): void {
        this.uiList["tips"].getComponent(Label).string = chect_data?.isReward ? i18n.tr(2001017) : i18n.tr(2001016)
        //奖励ICON
        let content = this.uiList["content"];
        content.removeAllChildren();
        if (chect_data?.rewardList) {
            for (let i = 1; i <= chect_data?.rewardList.length; i++) {
                let vo = chect_data?.rewardList[i - 1];
                let id = vo?.id;
                let amount = vo?.amount ? vo?.amount : 1;
                let propType = vo?.propType;
                let type = vo?.type;
                let score = vo?.score;

                GameComUtils.loadItem((item: BagItem) => {
                    if (id == null && type == 2) {
                        item.setEasyData(id, ItemType.Score, score);
                    } else {
                        item.setEasyData(id, propType, amount);
                    }
                    content.addChild(item.node);
                });
            }
        }

        this.onScreenSwitch();
    }

    onJump(gameId: number) {
        GameComUtils.popupJumpDlg(gameId);
    }

    onScreenSwitch() {
        if (Global.gameScreenType == ScreenType.Landscape) {
            this.uiList["panel"].angle = 0;
            // this.uiList["panel"].setScale(1, 1);
        } else {
            this.uiList["panel"].angle = 90;
            // this.uiList["panel"].setScale(0.8, 0.8);
        }
    }

    protected onDestroy(): void {
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
    }
}