/**
 * @description 彩金界面
 * @author guohuo
 */
import { _decorator, find, Node, Sprite, SpriteFrame, PageView, Component, ToggleContainer, instantiate, Toggle, Prefab, warn, Label, math, UITransform, ScrollView, macro } from 'cc';
import { Eventer } from '../../../../../scripts/framework/Eventer';
import { Global } from '../../../../../scripts/main/Global';
import { GameEventType } from '../../GameEventType';
import { ScreenType, UIView, UIZIndex } from '../../../../../scripts/framework/ui/UIView';
import { ComAcitivityTab } from '../common/ComActivityTab';
import { GameComUtils } from '../../utils/GameComUtils';
import { UIButton } from '../../../../../scripts/framework/ui/basic_ui/UIButton';
import { WinningsLangConfig } from './WinningsLangConfig';
import { UIManager } from '../../../../../scripts/framework/ui/UIManager';
import { UIID_GAME } from '../../UIGameDefined';
import { WinningRecordVo, WinningsMgr } from './WinningsMgr';
import { GameCommonModel } from '../../GameCommonModel';
import GamesData from '../../GamesData';
import TimeUtil from '../../../../../scripts/common/utils/TimeUtil';
import { RollValue } from '../../RollValue';
import { CCUtils } from '../../../../../scripts/common/utils/CCUtils';
import { WinningsBtn } from './WinningsBtn';
import { StatConst } from '../../stat/StatConst';
const { ccclass, property } = _decorator;

@ccclass('WinningsView')
export class WinningsView extends UIView {

    @property({ type: ComAcitivityTab, visible: true })
    private actTab: ComAcitivityTab;

    @property({ type: Node, visible: true })
    private landscape: Node;
    @property({ type: Node, visible: true })
    private portrait: Node;

    private thisNode: Node;
    private otherNode: Node;
    private thisContent: Node;
    private otherContent: Node;
    private btnHelp: UIButton;
    private labTip: Label;
    private jackpot: Node;
    private jackpot2: Node;
    private noDataNode: Node;
    private itemPlayer: Node;
    private itemOther: Node;
    private jackpotNode: Node;

    private selIndex: number = -1;

    private descMsg: any;

    private firOpenOtherGame: boolean = true;

    init(...args): void {
        this.node.zIndex = UIZIndex.actUI;
    }

    public onOpen() {
        this.addEvents();
        this.initMyUI();
        this.actTab.initData(WinningsLangConfig.get("tabNames"), "JACKPOTS", (i) => this.onTabClicked(i));

        let curDatas = WinningsMgr.getInstance().curDatas;
        if (curDatas.length) {
            this.actTab.selectTab(1);
        } else {
            this.actTab.selectTab(2);
        }

        // 每次进来获取一次吧
        WinningsMgr.getInstance().c2sWinningsJackpots();
        // 获取描述信息
        WinningsMgr.getInstance().c2sWinningsDescs();
        // 获取当前中奖记录
        WinningsMgr.getInstance().c2sWinningsRecords();

    }

    public onDestroy() {
        Eventer.getInstance().offName(GameEventType.winnings_jackpots, this);
        Eventer.getInstance().offName(GameEventType.winnings_records, this);
        Eventer.getInstance().offName(GameEventType.winnings_other_games, this);
        Eventer.getInstance().offName(GameEventType.winnings_descs, this);
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);

        clearInterval(this.timer);
    }

    private addEvents() {
        Eventer.getInstance().on(GameEventType.winnings_jackpots, this.onWinningsJackpots, this);
        Eventer.getInstance().on(GameEventType.winnings_records, this.onWinningsRecords, this);
        Eventer.getInstance().on(GameEventType.winnings_other_games, this.onWinningsOtherGames, this);
        Eventer.getInstance().on(GameEventType.winnings_descs, this.updateJackpotTitles, this);
        Eventer.getInstance().on(GameEventType.ScreenSwitch, this.onScreenSwitch, this);
    }

    onHelpClicked() {
        GameComUtils.c2sStat(StatConst.CLICK_BONUS_EXPLAIN);
        let desc = WinningsMgr.getInstance().descs?.desc?.defaultValue;
        UIManager.getInstance().open(UIID_GAME.UIComHelpDlg, desc);
    }

    onWinningsJackpots() {
        if (this.selIndex != 0) return;
        GameComUtils.c2sStat(StatConst.OPEN_BONUS_SCREEN);

        this.updateJackpots();
    }

    onWinningsRecords() {
        if (this.selIndex != 0) return;
        GameComUtils.c2sStat(StatConst.OPEN_BONUS_OTHER_GAME);

        this.updateRecords();
    }

    onWinningsOtherGames(others?: any[]) {
        if (this.selIndex != 1) return;

        setTimeout(WinningsMgr.getInstance().c2sWinningsOtherGames.bind(WinningsMgr.getInstance()), WinningsBtn.ReqInterval * 1000);
        this.updateOther(others);
    }

    private initMyUI() {
        let screenType = Global.gameScreenType;
        let isLandscape = screenType == ScreenType.Landscape;
        this.landscape.active = isLandscape;
        this.portrait.active = !isLandscape;

        this.thisNode = find("UILayer/WinningsView/" + screenType + "/this");
        this.otherNode = find("UILayer/WinningsView/" + screenType + "/other");
        this.thisContent = find("UILayer/WinningsView/" + screenType + "/this/listPlayer/view/content");
        this.otherContent = find("UILayer/WinningsView/" + screenType + "/other/listOther/view/content");
        this.btnHelp = find("UILayer/WinningsView/" + screenType + "/btnHelp").getComponent(UIButton);
        this.labTip = find("UILayer/WinningsView/" + screenType + "/labTip").getComponent(Label);
        this.jackpot = find("UILayer/WinningsView/" + screenType + "/jackpot");
        this.jackpot2 = find("UILayer/WinningsView/" + screenType + "/jackpot2");
        this.noDataNode = find("UILayer/WinningsView/" + screenType + "/noDataNode");
        this.itemPlayer = find("UILayer/WinningsView/" + screenType + "/this/itemPlayer");
        this.itemOther = find("UILayer/WinningsView/" + screenType + "/other/itemOther");
        this.jackpotNode = find("UILayer/WinningsView/" + screenType + "/this/layout");

        this.thisContent.removeAllChildren();
        this.otherContent.removeAllChildren();

        this.btnHelp.touchEndedFun = this.onHelpClicked.bind(this);

        this.thisNode.active = this.otherNode.active = this.noDataNode.active = false;
        this.jackpot.active = this.itemPlayer.active = this.itemOther.active = false;
        this.labTip.node.active = this.jackpot2.active = false;

        this.updateJackpotTitles();
    }

    updateJackpotTitles() {
        let descs = WinningsMgr.getInstance().descs;
        if (!descs) return;

        let names = descs.prizeSettingNames;
        let jackpotNode = this.jackpotNode;
        let num = Math.max(jackpotNode.children.length, names.length);

        for (let i = 0; i < num; ++i) {
            let node = jackpotNode.children[i];
            let data = names[i];
            if (data) {
                if (!node) {
                    node = instantiate(this.jackpot);
                    jackpotNode.addChild(node);
                }
                node.active = true;
                this.setJackpotTitle(node, data);
            } else {
                if (node) node.active = false;
            }
        }
    }

    private setJackpotTitle(item: Node, data: any) {
        if (data == null) return;
        let lab1 = item.getChildByName("lab1").getComponent(Label);
        let lab3 = item.getChildByName("lab3").getComponent(Label);
        lab1.string = data.name?.defaultValue || "unknown";
        lab3.string = "Jackpot " + data.level || "unknown";
    }

    private setJackpot(item: Node, data: any, index: number, isRoll = true, time = 1000) {
        let lab2 = item.getChildByName("lab2").getComponent(Label);
        let lab4 = item.getChildByName("lab4").getComponent(RollValue);
        lab4.prefix = Global.currencyName;

        lab2.string = Global.currencyName + (Number(data.maxPrize) * GameCommonModel.getInstance().coinRate).toString();
        let curVal = data.poolAmount * GameCommonModel.getInstance().coinRate;
        lab4.addValueTo(curVal, isRoll, time);
    }
    private updateJackpots() {
        let datas = WinningsMgr.getInstance().curDatas || [];
        let jackpotNode = this.jackpotNode;
        let num = Math.max(jackpotNode.children.length, datas.length);

        for (let i = 0; i < num; ++i) {
            let node = jackpotNode.children[i];
            let data = datas[i];
            if (data) {
                if (!node) {
                    node = instantiate(this.jackpot);
                    jackpotNode.addChild(node);
                }
                node.active = true;
                this.setJackpot(node, data, i, false);
            } else {
                if (node) node.active = false;
            }
        }
    }

    protected update(dt: number): void {
        if (this.selIndex == 0) {
            this.updateJackpots();
        }

        // this.updateRecordsOnFrame();
    }

    private setRecord(item: Node, data: any, index?: number) {
        let labName = item.getChildByName("labName").getComponent(Label);
        let labAmount = item.getChildByName("labAmount").getComponent(Label);
        let labDate = item.getChildByName("labDate").getComponent(Label);

        labName.string = data.name;
        labAmount.string = GamesData.formatValue(Number(data.amount) * GameCommonModel.getInstance().coinRate, 2, false, true);
        labDate.string = TimeUtil.timeStamp2String(data.date || 0);
    }

    private get curRecords() {
        return WinningsMgr.getInstance().curRecords || [];
    }

    // 分帧处理添加显示记录
    private usingRecords: WinningRecordVo[];
    private recordIndex: number = -1;
    private timer: number = 0;
    private updateRecordsOnFrame() {
        if (this.recordIndex == -1) return;

        let datas = this.usingRecords;
        if (this.recordIndex >= datas.length) {
            this.recordIndex = -1;
            clearInterval(this.timer);
            return;
        }

        let data = datas[this.recordIndex];
        let item = instantiate(this.itemPlayer);
        item.active = true;
        this.setRecord(item, data);
        this.thisContent.addChild(item);
        this.recordIndex++;
    }

    private updateRecords() {
        let records = this.curRecords;
        if (records.length == 0) return;

        if (this.usingRecords) {
            let lastRecord = this.usingRecords[this.usingRecords.length - 1];
            let newLastRecord = records[records.length - 1];
            let isChanged = false;
            for (let key in lastRecord) {
                if (lastRecord[key] != newLastRecord[key]) {
                    isChanged = true;
                    break;
                }
            }
            if (!isChanged) return;
        }

        // 启用分帧处理
        this.thisContent.removeAllChildren();
        this.usingRecords = records;
        this.recordIndex = 0;
        clearInterval(this.timer);
        this.timer = setInterval(this.updateRecordsOnFrame.bind(this), 80);

        // let datas = this.curRecords;
        // for (let i = 0; i < datas.length; ++i) {
        //     let data = datas[i];
        //     let item = instantiate(this.itemPlayer);
        //     item.active = true;
        //     this.setRecord(item, data);
        //     this.thisContent.addChild(item);
        // }
    }

    private updateCur() {
        let curDatas = WinningsMgr.getInstance().curDatas;
        if (!curDatas || curDatas.length == 0) {
            this.noDataNode.active = true;
        } else {
            this.thisNode.active = true;
            this.updateJackpots();
            this.updateRecords();
        }
    }

    private setOtherItem(item: Node, data: any, rollTime?) {
        let datas = data.prizeDetailDataList || [];
        let jackpotNode = item.getChildByName("layout");
        let num = Math.max(jackpotNode.children.length, datas.length);
        let names = WinningsMgr.getInstance().descs.prizeSettingNames;

        if (datas.length) datas.sort((a, b) => a.level - b.level);

        for (let i = 0; i < num; ++i) {
            let node = jackpotNode.children[i];
            let tmpData = datas[i];
            if (tmpData) {
                if (!node) {
                    node = instantiate(this.jackpot2);
                    jackpotNode.addChild(node);
                }
                node.active = true;
                this.setJackpot(node, tmpData, i, true, rollTime);
                this.setJackpotTitle(node, names[i]);
            } else {
                if (node) node.active = false;
            }
        }

        let gameIds = data.gameIds || [];
        let icon = item.getChildByName("icon").getComponent(Sprite);
        let btn = item.getChildByName("icon").getComponent(UIButton);
        if (gameIds.length == 0) {
            Log.e("游戏id列表为空");
            return;
        } else if (gameIds.length == 1) {
            GameComUtils.setGameIcon(gameIds[0], icon);
        } else {
            CCUtils.setSpriteFrame(icon, data.icon?.defaultValue);
        }
        btn.touchEndedFun = this.onJumpClicked.bind(this, gameIds);
    }

    onJumpClicked(gameIds: number[]) {
        if (gameIds.length == 1) {
            GameComUtils.c2sStat(StatConst.CLICK_BONUS_GO);
            GameComUtils.popupJumpDlg(gameIds[0], this.confirmCallback.bind(this));
        } else {
            UIManager.getInstance().open(UIID_GAME.ComGameListDlg, gameIds);
        }
    }

    private confirmCallback() {
        GameComUtils.c2sStat(StatConst.CLICK_BONUS_GO_CONFIRM);
    }

    private usingOthers: any[];
    private updateOther(datas: any[]) {
        datas = datas || [];
        if (datas.length) {
            this.otherNode.active = true;
            let maxNum = Math.max(this.otherContent.children.length, datas.length);
            for (let i = 0; i < maxNum; ++i) {
                let data = datas[i];
                let item = this.otherContent.children[i];
                if (data) {
                    if (!item) {
                        item = instantiate(this.itemOther);
                        item.name = data.winId.toString();
                    }
                    item.active = true;
                    this.setOtherItem(item, data, this.rollValueTime);
                    this.otherContent.addChild(item);
                } else if (item) {
                    item.active = false;
                }
            }
            this.firOpenOtherGame = false;
        } else {
            this.noDataNode.active = true;
        }
    }

    /**
     * 余额滚动时间
     */
    private get rollValueTime(): number {
        if (this.firOpenOtherGame)
            return 0;
        return WinningsBtn.ReqInterval * 1000; // 第一次也是5s滚动
    }

    private onTabClicked(index: number) {
        if (index == this.selIndex) return;

        this.selIndex = index;
        this.thisNode.active = this.otherNode.active = this.noDataNode.active = false;
        switch (index) {
            case 0:
                this.updateCur();
                break;
            case 1:
                this.otherNode.active = true;
                WinningsMgr.getInstance().c2sWinningsOtherGames();
                break;
        }
    }

    private onScreenSwitch(): void {
        this.initMyUI();
        let curIndex = this.selIndex + 1;
        this.selIndex = -1;
        this.actTab.screenSwitch();
        this.actTab.selectTab(curIndex);
    }

}

