/**
 * @description 通用（取消/确认）弹窗提示
 * @author guohuo
 */

import { _decorator, Component, Prefab, instantiate, EventTouch, NodeEventType, Node, SpriteFrame, Sprite, UITransform, ScrollView, size, Label } from 'cc';
import { ScreenType, UIView, UIZIndex } from '../../../../../scripts/framework/ui/UIView';
import { Eventer } from '../../../../../scripts/framework/Eventer';
import { GameEventType } from '../../GameEventType';
import { Global } from '../../../../../scripts/main/Global';
import { GameComUtils } from '../../utils/GameComUtils';
import { UIButtonState } from '../../../../../scripts/framework/ui/basic_ui/UIButtonState';
import { UIButton } from '../../../../../scripts/framework/ui/basic_ui/UIButton';
const { ccclass, property } = _decorator;

export interface ComTipsDlgArgs {
    title?: string; // 标题
    content: string; // 内容
    btnNames?: string[]; // 按钮名字
    btnClickFun1?: Function; // 左边按钮回调
    btnClickFun2?: Function; // 右边按钮回调

    gotoGameId?: number; // 要去某一个游戏的弹窗
}

@ccclass('ComTipsDlg')
export class ComTipsDlg extends UIView {
    private _data: ComTipsDlgArgs = null;
    private _uiList: { [key: string]: Node } = {};

    init(...args): void {
        this.node.zIndex = UIZIndex.actUI;
    }

    onLoad(): void {
        this.initUI();
        this.bindEvent();
    }

    start() {
        Eventer.getInstance().on(GameEventType.ScreenSwitch, this.onScreenSwitch, this);
    }

    onScreenSwitch() {
        if (Global.gameScreenType == ScreenType.Landscape) {
            this._uiList["panel"].angle = 0;
        } else {
            this._uiList["panel"].angle = 90;
        }
    }


    protected onDestroy(): void {
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
    }

    public initUI() {
        this.SerializableUIControlNode(this.node);
    }

    public bindEvent() {
        let closeBtn = this._uiList["closeBtn"];
        closeBtn.getComponent(UIButton).touchEndedFun = this.close.bind(this);

        //跳转到其他界面
        this._uiList["btn1"].getComponent(UIButton).touchEndedFun = () => {
            if (this._data.btnClickFun1) this._data.btnClickFun1();
            this.close();
        }

        this._uiList["btn2"].getComponent(UIButton).touchEndedFun = () => {
            if (this._data.btnClickFun2) this._data.btnClickFun2();
            this.close();
        }
    }

    public onOpen(obj: ComTipsDlgArgs): void {
        this._data = obj;
        if (!obj.btnNames) obj.btnNames = [];

        this._uiList["titleLab"].getComponent(Label).string = obj.title || "SYSTEM";
        this._uiList["contentLab"].getComponent(Label).string = obj.content;
        this._uiList["btnLab1"].getComponent(Label).string = obj.btnNames[0] || "CANCEL";
        this._uiList["btnLab2"].getComponent(Label).string = obj.btnNames[1] || "CONFIRM";

        if (obj.gotoGameId) {
            GameComUtils.getGameName(obj.gotoGameId, (name: string) => {
                this._uiList["contentLab"].getComponent(Label).string = obj.content.replace(obj.gotoGameId.toString(), name);
            });
        }

        this.onScreenSwitch();
    }

    private SerializableUIControlNode(root: Node) {
        if (!root) {
            return;
        }
        let children = root.children;
        for (let k in children) {
            let child = children[k];
            let name = child.name;
            this._uiList[name] = child;
            if (child.children.length >= 1) {
                this.SerializableUIControlNode(child);
            }
        }
    }
}